function showLoading(show) {
    const overlay = document.getElementById('loadingOverlay');
    if (overlay) overlay.classList.toggle('active', show);
}

function showToast(message, type = 'success', duration = 3000) {
    const container = document.getElementById('toastContainer');
    if (!container) return;
    
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    
    const icons = {
        success: 'fa-check-circle',
        error: 'fa-exclamation-circle',
        warning: 'fa-exclamation-triangle',
        info: 'fa-info-circle'
    };
    
    toast.innerHTML = `<i class="fas ${icons[type] || icons.success}"></i><span>${message}</span>`;
    container.appendChild(toast);
    
    setTimeout(() => {
        toast.classList.add('toast-exit');
        setTimeout(() => toast.remove(), 300);
    }, duration);
}

function getToken() {
    return localStorage.getItem('token');
}

let authRedirectInProgress = false;

function clearAuthSession() {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
}

function redirectToLogin() {
    if (authRedirectInProgress) return;

    authRedirectInProgress = true;
    clearAuthSession();
    showLoading(false);

    // replace مانع بازگشت کاربر به صفحه‌ای می‌شود که توکن نامعتبر داشته است.
    window.location.replace('/login');
}

// ============================================
// ✅ API FETCH - نسخه اصلاح شده برای اتصال به سرور واقعی
// ============================================

const adminRequestCache = new Map();
const adminPendingRequests = new Map();
let adminRateLimitCooldownUntil = 0;

function adminNormalizeRequestMethod(options = {}) {
    return String(options.method || 'GET').toUpperCase();
}

function adminRequestCacheKey(endpoint, options = {}) {
    return `${adminNormalizeRequestMethod(options)}:${endpoint}:${options.body || ''}`;
}

function adminSleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function adminGetCachedResponse(key, maxAge = 20000) {
    const cached = adminRequestCache.get(key);
    if (!cached) return null;
    if ((Date.now() - cached.time) > maxAge) return null;
    return cached.data;
}

function adminInvalidateReadCaches(patterns = []) {
    const list = Array.isArray(patterns) ? patterns : [patterns];
    for (const key of Array.from(adminRequestCache.keys())) {
        if (!String(key).startsWith('GET:')) continue;
        if (!list.length || list.some(pattern => String(key).includes(String(pattern)))) {
            adminRequestCache.delete(key);
        }
    }
    for (const key of Array.from(adminPendingRequests.keys())) {
        if (!String(key).startsWith('GET:')) continue;
        if (!list.length || list.some(pattern => String(key).includes(String(pattern)))) {
            adminPendingRequests.delete(key);
        }
    }
}

async function fetchAPI(endpoint, options = {}) {
    const token = getToken();
    const url = `${API_BASE_URL}${endpoint}`;
    const method = adminNormalizeRequestMethod(options);
    const isReadRequest = method === 'GET';
    const key = adminRequestCacheKey(endpoint, options);

    if (isReadRequest) {
        const cached = adminGetCachedResponse(key, endpoint === '/auth/me' || endpoint === '/settings' ? 60000 : 12000);
        if (cached) return cached;
        if (adminPendingRequests.has(key)) return adminPendingRequests.get(key);
    }

    const runRequest = async () => {
        const now = Date.now();
        if (now < adminRateLimitCooldownUntil && isReadRequest) {
            const cached = adminRequestCache.get(key);
            if (cached) return cached.data;
            await adminSleep(Math.min(adminRateLimitCooldownUntil - now, 2500));
        }

        console.log(`Fetching: ${url}`, options);

        try {
            const response = await fetch(url, {
                ...options,
                headers: {
                    'Content-Type': 'application/json',
                    ...(token && { 'Authorization': `Bearer ${token}` }),
                    ...options.headers
                }
            });

            if (!response.ok) {
                const errorPayload = await response.json().catch(() => ({
                    error: `HTTP ${response.status}`
                }));
                const errorMessage = errorPayload.error || errorPayload.message || `خطای سرور: ${response.status}`;

                if (response.status === 429) {
                    const retryAfter = Number(response.headers.get('Retry-After') || 0);
                    adminRateLimitCooldownUntil = Date.now() + Math.max(4000, Math.min(30000, retryAfter ? retryAfter * 1000 : 8000));
                    const cached = adminRequestCache.get(key);
                    if (cached && isReadRequest) return cached.data;
                    const rateError = new Error('تعداد درخواست‌ها زیاد شده است. چند ثانیه صبر کنید و دوباره تلاش کنید.');
                    rateError.status = 429;
                    rateError.name = 'RateLimitError';
                    throw rateError;
                }

                // سرور برای توکن نامعتبر 403 برمی‌گرداند. فقط خطاهای احراز هویت
                // باعث پاک شدن نشست می‌شوند؛ خطاهای 403 مربوط به سطح دسترسی حفظ می‌شوند.
                const isInvalidToken = response.status === 403 && /توکن|token|jwt|منقضی/i.test(errorMessage);
                const isAuthenticationError = response.status === 401 || isInvalidToken;

                if (isAuthenticationError) {
                    const authError = new Error(errorMessage || 'نشست شما منقضی شده است');
                    authError.name = 'AuthenticationError';
                    authError.status = response.status;
                    redirectToLogin();
                    throw authError;
                }

                const apiError = new Error(errorMessage);
                apiError.status = response.status;
                throw apiError;
            }

            const data = await response.json();
            if (isReadRequest) {
                adminRequestCache.set(key, { data, time: Date.now() });
            } else {
                adminInvalidateReadCaches([endpoint.split('?')[0].replace(/\/\d+(?:\/.*)?$/, '') || '/admin/modules/grades']);
                if (endpoint.includes('/admin/modules/grades')) adminInvalidateReadCaches(['/admin/modules/grades', '/admin/modules/grades/options']);
            }
            console.log(`Response from ${endpoint}:`, data);
            return data;
        } catch (error) {
            console.error(`API Error on ${endpoint}:`, error);
            throw error;
        } finally {
            if (isReadRequest) adminPendingRequests.delete(key);
        }
    };

    const promise = runRequest();
    if (isReadRequest) adminPendingRequests.set(key, promise);
    return promise;
}

