// ============================================
// توابع تاریخ شمسی و تبدیل عدد - نسخه یکپارچه و بدون تعریف تکراری
// ============================================

function normalizeDateDigits(value) {
    return String(value ?? '')
        .replace(/[۰-۹]/g, digit => '۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))
        .replace(/[٠-٩]/g, digit => '٠١٢٣٤٥٦٧٨٩'.indexOf(digit));
}

function toEnglishNumber(str) {
    return normalizeDateDigits(str);
}

function toPersianNumber(value) {
    if (value === undefined || value === null || value === '') return '۰';
    const persianDigits = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];
    return String(value).replace(/\d/g, digit => persianDigits[Number(digit)]);
}

function div(a, b) {
    return Math.floor(a / b);
}

function isLeapYear(year) {
    return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

function gregorianToJalali(gy, gm, gd) {
    gy = Number(gy); gm = Number(gm); gd = Number(gd);
    if (![gy, gm, gd].every(Number.isFinite)) return [0, 0, 0];

    const gDaysInMonth = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    let jy;
    if (gy > 1600) {
        jy = 979;
        gy -= 1600;
    } else {
        jy = 0;
        gy -= 621;
    }

    const gy2 = gm > 2 ? gy + 1 : gy;
    let days = (365 * gy) + div(gy2 + 3, 4) - div(gy2 + 99, 100) + div(gy2 + 399, 400) - 80 + gd + gDaysInMonth[gm - 1];

    jy += 33 * div(days, 12053);
    days %= 12053;
    jy += 4 * div(days, 1461);
    days %= 1461;

    if (days > 365) {
        jy += div(days - 1, 365);
        days = (days - 1) % 365;
    }

    const jm = days < 186 ? 1 + div(days, 31) : 7 + div(days - 186, 30);
    const jd = 1 + (days < 186 ? days % 31 : (days - 186) % 30);
    return [jy, jm, jd];
}

function jalaliToGregorianManual(jy, jm, jd) {
    jy = Number(normalizeDateDigits(jy));
    jm = Number(normalizeDateDigits(jm));
    jd = Number(normalizeDateDigits(jd));
    if (![jy, jm, jd].every(Number.isFinite)) return [0, 0, 0];

    jy += 1595;
    let days = -355668 + (365 * jy) + div(jy, 33) * 8 + div((jy % 33) + 3, 4) + jd;
    days += jm < 7 ? (jm - 1) * 31 : ((jm - 7) * 30) + 186;

    let gy = 400 * div(days, 146097);
    days %= 146097;

    if (days > 36524) {
        gy += 100 * div(--days, 36524);
        days %= 36524;
        if (days >= 365) days++;
    }

    gy += 4 * div(days, 1461);
    days %= 1461;

    if (days > 365) {
        gy += div(days - 1, 365);
        days = (days - 1) % 365;
    }

    let gd = days + 1;
    const salA = [0, 31, isLeapYear(gy) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let gm = 1;
    while (gm <= 12 && gd > salA[gm]) {
        gd -= salA[gm];
        gm++;
    }

    return [gy, gm, gd];
}

function jalaliToGregorian(jy, jm, jd) {
    if (arguments.length === 1) {
        const normalized = normalizeDateDigits(jy).trim();
        const parts = normalized.split(/[\/\-.]/).filter(Boolean);
        if (parts.length < 3) return '';
        [jy, jm, jd] = parts;
    }

    jy = Number(normalizeDateDigits(jy));
    jm = Number(normalizeDateDigits(jm));
    jd = Number(normalizeDateDigits(jd));
    if (!Number.isInteger(jy) || !Number.isInteger(jm) || !Number.isInteger(jd)) return '';

    if (jy > 1700) {
        return `${String(jy).padStart(4, '0')}-${String(jm).padStart(2, '0')}-${String(jd).padStart(2, '0')}`;
    }

    if (jm < 1 || jm > 12 || jd < 1 || jd > 31) return '';
    const [gy, gm, gd] = jalaliToGregorianManual(jy, jm, jd);
    if (!gy || !gm || !gd) return '';
    return `${String(gy).padStart(4, '0')}-${String(gm).padStart(2, '0')}-${String(gd).padStart(2, '0')}`;
}

function toJalali(dateString) {
    if (!dateString) return '';
    try {
        const date = dateString instanceof Date ? dateString : new Date(dateString);
        if (Number.isNaN(date.getTime())) return String(dateString);
        const [jy, jm, jd] = gregorianToJalali(date.getFullYear(), date.getMonth() + 1, date.getDate());
        return `${jy}/${String(jm).padStart(2, '0')}/${String(jd).padStart(2, '0')}`;
    } catch (error) {
        console.warn('Error in toJalali:', error);
        return String(dateString);
    }
}

function getTodayJalali() {
    return toJalali(new Date());
}

function getTodayJalaliPersian() {
    return toPersianNumber(getTodayJalali());
}

function toJalaliFull(dateString) {
    if (!dateString) return '-';
    try {
        const date = dateString instanceof Date ? dateString : new Date(dateString);
        if (Number.isNaN(date.getTime())) return String(dateString);
        const [jy, jm, jd] = gregorianToJalali(date.getFullYear(), date.getMonth() + 1, date.getDate());
        const monthNames = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
        return `${toPersianNumber(jy)} ${monthNames[jm - 1]} ${toPersianNumber(jd)}`;
    } catch (error) {
        console.warn('Error in toJalaliFull:', error);
        return String(dateString);
    }
}

function formatNumber(num) {
    if (num === undefined || num === null || num === '') return '۰';
    const number = Number(num);
    if (!Number.isFinite(number)) return toPersianNumber(num);
    const formatted = Math.floor(number).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    return toPersianNumber(formatted);
}



// تبدیل همه اعداد نمایشی صفحه به فارسی، بدون دستکاری فرم‌ها و اسکریپت‌ها
function persianizePageNumbers(root = document.body) {
    if (!root) return;
    const skipTags = new Set(['SCRIPT', 'STYLE', 'INPUT', 'TEXTAREA', 'SELECT', 'OPTION', 'CODE', 'PRE']);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode(node) {
            const parent = node.parentElement;
            if (!parent || skipTags.has(parent.tagName)) return NodeFilter.FILTER_REJECT;
            if (parent.closest('[data-en-digits="true"], .en-digits, .cm-code, .cm-modal-final-code, .tracking-code, .reg-tracking')) return NodeFilter.FILTER_REJECT;
            if (!/[0-9٠-٩]/.test(node.nodeValue)) return NodeFilter.FILTER_REJECT;
            return NodeFilter.FILTER_ACCEPT;
        }
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach(node => { node.nodeValue = toPersianNumber(node.nodeValue); });
}

let persianizeObserver = null;
function initPersianNumberObserver() {
    persianizePageNumbers(document.body);
    if (persianizeObserver) persianizeObserver.disconnect();
    let timer = null;
    persianizeObserver = new MutationObserver(() => {
        clearTimeout(timer);
        timer = setTimeout(() => persianizePageNumbers(document.body), 80);
    });
    persianizeObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
}

