function getVisibleSchoolUserTotal(counts = {}, fallbackTotal = 0) {
    const visibleRoles = ['admin', 'principal', 'student', 'teacher', 'parent', 'counselor', 'cultural_deputy', 'executive_deputy', 'cultural_assistant', 'executive_assistant'];
    const total = visibleRoles.reduce((sum, role) => sum + Number(counts[role] || 0), 0);
    return total || Number(fallbackTotal || 0);
}

