// محاسبه سن از تاریخ تولد
function calculateAge(birthDate) {
    if (!birthDate) return null;
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
        age--;
    }
    return age;
}

// اعتبارسنجی ورودی تاریخ شمسی
function isValidPersianDate(dateStr) {
    const pattern = /^[1-4]\d{3}\/(0[1-9]|1[0-2])\/(0[1-9]|[12]\d|3[01])$/;
    if (!pattern.test(dateStr)) return false;
    
    const parts = dateStr.split('/');
    const year = parseInt(parts[0]);
    const month = parseInt(parts[1]);
    const day = parseInt(parts[2]);
    
    // بررسی روزهای ماه
    const daysInMonth = [31, 31, 31, 31, 31, 31, 30, 30, 30, 30, 30, 29];
    if (day > daysInMonth[month - 1]) return false;
    
    // بررسی سال کبیسه شمسی برای ماه اسفند
    if (month === 12 && day === 30) {
        // سال کبیسه شمسی هر 4 سال یکبار (به جز سال‌های 1, 5, 9, ...)
        const isLeap = (year % 33 === 1 || year % 33 === 5 || year % 33 === 9 || 
                        year % 33 === 13 || year % 33 === 17 || year % 33 === 22 || 
                        year % 33 === 26 || year % 33 === 30);
        if (!isLeap) return false;
    }
    
    return true;
}

