function adminModuleEscape(value){return String(value ?? '').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));}
function adminModuleFaNum(value){return String(value ?? 0).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);}
