let ADMIN_GRADE_MODULE_CACHE = { options: {}, rows: [], filters: {} };
let ADMIN_ATTENDANCE_MODULE_CACHE = { options: {}, rows: [], filters: {} };
function adminModuleOptionTags(items = [], selected = '', allLabel = ''){
    const list = Array.isArray(items) ? items : [];
    const head = allLabel ? `<option value="all">${adminModuleEscape(allLabel)}</option>` : '';
    return head + list.map(item => `<option value="${adminModuleEscape(item.value ?? item.id ?? '')}" ${String(selected)===String(item.value ?? item.id ?? '')?'selected':''}>${adminModuleEscape(item.label ?? item.name ?? item.title ?? item.value ?? '')}</option>`).join('');
}

function adminModuleNormalizeOptions(items = [], selected = '', allLabel = ''){
    const list = Array.isArray(items) ? items : [];
    const normalized = [];
    if(allLabel) normalized.push({value:'all', label:allLabel, grade:'', class_id:''});
    list.forEach(item => {
        const value = String(item?.value ?? item?.id ?? '');
        const label = String(item?.label ?? item?.name ?? item?.title ?? item?.value ?? '');
        if(!value && !label) return;
        normalized.push({
            value,
            label,
            grade: String(item?.grade ?? ''),
            class_id: String(item?.class_id ?? item?.classId ?? ''),
            teacher_id: String(item?.teacher_id ?? '')
        });
    });
    const selectedValue = String(selected || (allLabel ? 'all' : ''));
    return {items: normalized, selected: selectedValue, current: normalized.find(item => String(item.value) === selectedValue) || normalized[0] || {value:'', label:'انتخاب کنید'}};
}
function adminRenderSmartDropdown(name, items = [], selected = '', allLabel = '', placeholder = 'جستجو در لیست...'){
    const data = adminModuleNormalizeOptions(items, selected, allLabel);
    const safeName = adminModuleEscape(name);
    const uid = `amp_${String(name).replace(/[^a-zA-Z0-9_\-]/g,'_')}_${Math.random().toString(36).slice(2,8)}`;
    const optionsHtml = data.items.map(item => {
        const active = String(item.value) === String(data.current.value) ? ' is-active' : '';
        return `<button type="button" class="amp-smart-option${active}" data-value="${adminModuleEscape(item.value)}" data-label="${adminModuleEscape(item.label)}" data-grade="${adminModuleEscape(item.grade)}" data-class-id="${adminModuleEscape(item.class_id)}" data-teacher-id="${adminModuleEscape(item.teacher_id)}" onclick="adminSmartDropdownChoose(event)"><span>${adminModuleEscape(item.label)}</span><i class="fas fa-check"></i></button>`;
    }).join('');
    return `<div class="amp-smart-dropdown" data-smart-name="${safeName}" id="${uid}">
        <input type="hidden" name="${safeName}" value="${adminModuleEscape(data.current.value)}">
        <button type="button" class="amp-smart-trigger" onclick="adminSmartDropdownToggle(event)" aria-haspopup="listbox" aria-expanded="false">
            <span class="amp-smart-current">${adminModuleEscape(data.current.label)}</span>
            <i class="fas fa-chevron-down"></i>
        </button>
        <div class="amp-smart-menu" role="listbox">
            <label class="amp-smart-search"><i class="fas fa-search"></i><input type="text" oninput="adminSmartDropdownSearch(event)" placeholder="${adminModuleEscape(placeholder)}"></label>
            <div class="amp-smart-options">${optionsHtml || '<div class="amp-smart-empty">موردی برای نمایش وجود ندارد</div>'}</div>
        </div>
    </div>`;
}
function adminSmartDropdownCloseAll(except){
    document.querySelectorAll('.amp-smart-dropdown.is-open').forEach(box => {
        if(box === except) return;
        box.classList.remove('is-open');
        box.querySelector('.amp-smart-trigger')?.setAttribute('aria-expanded','false');
    });
}
function adminSmartDropdownToggle(event){
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const box = event.target.closest('.amp-smart-dropdown');
    if(!box) return;
    const willOpen = !box.classList.contains('is-open');
    adminSmartDropdownCloseAll(box);
    box.classList.toggle('is-open', willOpen);
    box.querySelector('.amp-smart-trigger')?.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    if(willOpen){
        const search = box.querySelector('.amp-smart-search input');
        if(search){ search.value=''; adminSmartDropdownSearch({target:search}); setTimeout(()=>search.focus(),30); }
    }
}
function adminSmartDropdownSetValue(name, value='all', label='', scope=document){
    const root = scope || document;
    const box = root.querySelector(`.amp-smart-dropdown[data-smart-name="${name}"]`);
    if(!box) return;
    const input = box.querySelector('input[type="hidden"]');
    if(input) input.value = value;
    const activeOption = [...box.querySelectorAll('.amp-smart-option')].find(btn => String(btn.dataset.value) === String(value)) || box.querySelector('.amp-smart-option');
    const current = box.querySelector('.amp-smart-current');
    box.querySelectorAll('.amp-smart-option').forEach(btn => btn.classList.remove('is-active'));
    if(activeOption){
        activeOption.classList.add('is-active');
        if(current) current.textContent = label || activeOption.dataset.label || activeOption.textContent.trim();
    }else if(current){
        current.textContent = label || 'انتخاب کنید';
    }
}
function adminSmartDropdownChoose(event){
    event?.preventDefault?.();
    event?.stopPropagation?.();
    const option = event.target.closest('.amp-smart-option');
    const box = option?.closest('.amp-smart-dropdown');
    if(!option || !box) return;
    const value = option.dataset.value || '';
    const label = option.dataset.label || option.textContent.trim();
    const input = box.querySelector('input[type="hidden"]');
    if(input) input.value = value;
    const current = box.querySelector('.amp-smart-current');
    if(current) current.textContent = label;
    box.querySelectorAll('.amp-smart-option').forEach(btn => btn.classList.remove('is-active'));
    option.classList.add('is-active');
    box.classList.remove('is-open');
    box.querySelector('.amp-smart-trigger')?.setAttribute('aria-expanded','false');
    if(box.closest('#adminGradesFilterForm')){
        const fieldName = box.dataset.smartName || '';
        const filterForm = box.closest('#adminGradesFilterForm');
        if(fieldName === 'grade'){
            adminSmartDropdownSetValue('class_id', 'all', 'انتخاب کلاس', filterForm);
            adminSmartDropdownSetValue('student_id', 'all', 'انتخاب دانش‌آموز', filterForm);
        }
        if(fieldName === 'class_id'){
            adminSmartDropdownSetValue('student_id', 'all', 'انتخاب دانش‌آموز', filterForm);
        }
        adminScheduleGradeFilterApply();
    }
    if(box.closest('#adminReportCardsFilterForm')){
        const fieldName = box.dataset.smartName || '';
        const reportCardsForm = box.closest('#adminReportCardsFilterForm');
        if(fieldName === 'grade'){
            adminSmartDropdownSetValue('class_id', 'all', 'انتخاب کلاس', reportCardsForm);
            adminSmartDropdownSetValue('student_id', 'all', 'انتخاب دانش‌آموز', reportCardsForm);
        }
        if(fieldName === 'class_id'){
            adminSmartDropdownSetValue('student_id', 'all', 'انتخاب دانش‌آموز', reportCardsForm);
        }
        setTimeout(() => adminApplyReportCardFilters({ preventDefault(){} }), 120);
    }
    if(box.closest('#adminAttendanceFilterForm')){
        const fieldName = box.dataset.smartName || '';
        const attendanceForm = box.closest('#adminAttendanceFilterForm');
        if(fieldName === 'grade') adminSmartDropdownSetValue('class_id', 'all', 'همه کلاس‌ها', attendanceForm);
    }
    if(box.closest('#adminQuickGradeForm')){
        adminGradeModalDropdownChanged(box.dataset.smartName || '');
    }
    const reportForm = box.closest('#adminReportGradeCellForm');
    if(reportForm && box.dataset.smartName === 'grade_text'){
        setTimeout(() => adminSubmitReportGrade({ preventDefault(){}, target: reportForm }), 80);
    }
}
function adminSmartDropdownSearch(event){
    const input = event?.target;
    const box = input?.closest('.amp-smart-dropdown');
    if(!box) return;
    const needle = String(input.value || '').trim().toLowerCase();
    let visible = 0;
    box.querySelectorAll('.amp-smart-option').forEach(btn => {
        const hit = !needle || btn.textContent.toLowerCase().includes(needle);
        btn.style.display = hit ? '' : 'none';
        if(hit) visible++;
    });
    let empty = box.querySelector('.amp-smart-empty-live');
    if(!empty){
        empty = document.createElement('div');
        empty.className = 'amp-smart-empty amp-smart-empty-live';
        empty.textContent = 'موردی پیدا نشد';
        box.querySelector('.amp-smart-options')?.appendChild(empty);
    }
    empty.style.display = visible ? 'none' : 'block';
}
if(!window.__adminSmartDropdownOutsideBound){
    window.__adminSmartDropdownOutsideBound = true;
    document.addEventListener('click', event => {
        if(!event.target.closest('.amp-smart-dropdown')) adminSmartDropdownCloseAll();
    });
    document.addEventListener('keydown', event => {
        if(event.key === 'Escape') adminSmartDropdownCloseAll();
    });
}

function adminAttendanceOptions(data = {}){
    return data.options || ADMIN_ATTENDANCE_MODULE_CACHE.options || {
        academicYears:[{value:'current',label:'سال تحصیلی جاری'}], grades:[], classes:[], students:[],
        recordTypes:[{value:'all',label:'همه رکوردها'},{value:'attendance',label:'حضور دانش‌آموزان'},{value:'staff',label:'حضور پرسنل'},{value:'discipline',label:'موارد انضباطی'}],
        statuses:[{value:'all',label:'همه وضعیت‌ها'},{value:'present',label:'حاضر'},{value:'absent',label:'غایب'},{value:'late',label:'تأخیر'},{value:'excused',label:'موجه'}]
    };
}
function adminAttendanceCleanFilters(filters = {}){
    const result = {};
    ['academic_year','grade','class_id','student_id','record_type','status','date','q'].forEach(key => {
        const value = String(filters?.[key] ?? '').trim();
        if(value && value !== 'all') result[key] = value;
    });
    return result;
}
function adminAttendanceFormPayload(form){
    const raw = form ? Object.fromEntries(new FormData(form).entries()) : {};
    const payload = {...raw};
    const jalaliDate = String(raw.date || '').trim();
    if(jalaliDate){
        payload.date_jalali = jalaliDate;
        payload.date = jalaliToGregorian(jalaliDate) || jalaliDate.replace(/\//g,'-');
    }
    return payload;
}
function adminAttendanceDisplayDate(filters = {}){
    if(filters.date_jalali) return filters.date_jalali;
    if(filters.date && /^\d{4}-\d{2}-\d{2}/.test(String(filters.date))) return toPersianNumber(toJalali(filters.date));
    if(filters.date) return toPersianNumber(String(filters.date).replace(/-/g,'/'));
    return toPersianNumber(getTodayJalali());
}
async function adminApplyAttendanceFilters(event){
    event?.preventDefault?.();
    const form = document.getElementById('adminAttendanceFilterForm');
    const payload = adminAttendanceFormPayload(form);
    const filters = adminAttendanceCleanFilters(payload);
    if(payload.date_jalali) filters.date_jalali = payload.date_jalali;
    ADMIN_ATTENDANCE_MODULE_CACHE.filters = filters;
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([key,value]) => { if(key !== 'date_jalali') params.set(key, value); });
    showLoading(true);
    try{
        const data = await fetchAPI('/admin/modules/attendance' + (params.toString() ? '?' + params.toString() : ''));
        ADMIN_ATTENDANCE_MODULE_CACHE = { options: data.options || ADMIN_ATTENDANCE_MODULE_CACHE.options || {}, rows: data.items || data.attendance || [], filters };
        const contentArea = document.getElementById('contentArea');
        if(contentArea){
            contentArea.innerHTML = adminRenderConsolidatedModulePage('attendance', ADMIN_NEW_MODULE_PAGES.attendance, data, data.items || data.attendance || [], data.summary || {});
            bindAdminModuleForms('attendance');
        }
    }catch(error){
        showToast(error.message || 'خطا در فیلتر حضور و انضباط', 'error');
    }finally{showLoading(false); const lo=document.getElementById('loadingOverlay'); if(lo)lo.style.display='none';}
}
function adminClearAttendanceFilters(){
    ADMIN_ATTENDANCE_MODULE_CACHE.filters = {};
    loadAdminNewModulePage('attendance');
}
function adminInitAttendancePageEnhancements(){
    const dateInput = document.getElementById('attendanceFilterDate');
    if(dateInput){
        dateInput.setAttribute('readonly','readonly');
        dateInput.setAttribute('data-persian-date','true');
        initPersianDatepicker('attendanceFilterDate');
    }
    document.querySelectorAll('#adminModuleUtilityModal input[data-persian-date]').forEach(input => {
        if(!input.id) input.id = 'att_modal_date_' + Math.random().toString(36).slice(2,8);
        input.setAttribute('readonly','readonly');
        initPersianDatepicker(input.id);
    });
}
function adminAttendanceStatusText(status=''){
    const map = {present:'حاضر', absent:'غایب', late:'تأخیر', excused:'موجه', leave:'مرخصی', discipline:'انضباطی', warning:'تذکر', encouragement:'تشویقی'};
    return map[status] || status || '-';
}
function adminAttendanceTypeText(type=''){
    const map = {attendance:'حضور دانش‌آموز', staff:'حضور پرسنل', discipline:'انضباطی'};
    return map[type] || type || 'حضور دانش‌آموز';
}

function adminGradeTypeLabel(value){
    const found = (ADMIN_GRADE_MODULE_CACHE.options?.gradeTypes || []).find(item => item.value === value);
    return found?.label || value || 'مستمر';
}
function adminDescriptiveLabel(value){
    const found = (ADMIN_GRADE_MODULE_CACHE.options?.descriptiveLevels || []).find(item => item.value === value || item.label === value);
    return found?.label || value || '-';
}
function adminGradeDisplayValue(row){
    if(!row) return '-';
    if(row.absence_status && row.absence_status !== 'none'){
        const labels={exam_absent:'غیبت در امتحان',excused_absent:'غیبت موجه',unexcused_absent:'غیبت غیرموجه'};
        return labels[row.absence_status] || row.absence_status;
    }
    if(row.grade_mode === 'descriptive') return adminDescriptiveLabel(row.grade_text);
    const val = row.grade_value ?? row.average;
    return val === null || val === undefined || val === '' ? '-' : adminModuleFaNum(Number(val).toFixed(Number(val)%1?2:0));
}
function adminGradeBadge(row){
    if(row?.grade_mode === 'descriptive'){
        const key = row.grade_text;
        const type = key === 'excellent' || key === 'good' || key === 'خیلی خوب' || key === 'خوب' ? 'good' : key === 'acceptable' || key === 'قابل قبول' ? 'mid' : 'bad';
        return adminModuleStatusBadge(adminGradeDisplayValue(row), type);
    }
    return adminModuleScoreCell(row?.grade_value ?? row?.average);
}
function adminGradePassBadge(row){
    const text = row?.pass_status || (Number((row?.grade_value ?? row?.average) || 0) >= 10 ? 'قبول' : 'مردود');
    const type = String(text).includes('قبول') ? 'good' : String(text).includes('ثبت') ? 'info' : 'bad';
    return adminModuleStatusBadge(text, type);
}
function adminGradeRowText(row){
    return Object.values(row || {}).map(v => String(v ?? '')).join(' ').toLowerCase();
}
let ADMIN_GRADE_FILTER_TIMER = null;
function adminScheduleGradeFilterApply(){
    clearTimeout(ADMIN_GRADE_FILTER_TIMER);
    ADMIN_GRADE_FILTER_TIMER = setTimeout(() => adminApplyGradeFilters(), 350);
}
function adminQuickFilterGrades(value){
    const needle = String(value || '').trim().toLowerCase();
    document.querySelectorAll('#adminGradesTableWrap tbody tr').forEach(tr => {
        tr.style.display = !needle || tr.textContent.toLowerCase().includes(needle) ? '' : 'none';
    });
    adminScheduleGradeFilterApply();
}
async function adminFetchGradeOptionsForFilters(filters = {}){
    const params = new URLSearchParams();
    ['grade','class_id','student_id'].forEach(key => {
        const value = filters?.[key];
        if(value && value !== 'all') params.set(key, value);
    });
    try{
        const data = await fetchAPI('/admin/modules/grades/options' + (params.toString() ? '?' + params.toString() : ''));
        return data.options || ADMIN_GRADE_MODULE_CACHE.options || {};
    }catch(error){
        console.warn('grade options refresh failed', error);
        return ADMIN_GRADE_MODULE_CACHE.options || {};
    }
}

async function adminApplyGradeFilters(event){
    event?.preventDefault?.();
    const form = document.getElementById('adminGradesFilterForm');
    const params = new URLSearchParams();
    const filters = {};
    if(form){
        Object.entries(Object.fromEntries(new FormData(form).entries())).forEach(([key,value]) => {
            if(value && value !== 'all'){
                filters[key] = value;
                params.set(key, value);
            }
        });
    }
    ADMIN_GRADE_MODULE_CACHE.filters = filters;
    const contentArea = document.getElementById('contentArea');
    const hasRequired = Boolean(filters.grade && filters.class_id && filters.student_id);
    showLoading(true);
    try{
        if(!hasRequired){
            const refreshedOptions = (filters.grade || filters.class_id)
                ? await adminFetchGradeOptionsForFilters(filters)
                : (ADMIN_GRADE_MODULE_CACHE.options || {});
            ADMIN_GRADE_MODULE_CACHE = {
                options: refreshedOptions,
                rows: [],
                filters
            };
            const data = { success:true, options: refreshedOptions, items: [], grades: [], summary: {} };
            if(contentArea){
                contentArea.innerHTML = adminRenderConsolidatedModulePage('grades', ADMIN_NEW_MODULE_PAGES.grades, data, [], data.summary || {});
                bindAdminModuleForms('grades');
            }
            return;
        }
        const data = await fetchAPI('/admin/modules/grades' + (params.toString() ? '?' + params.toString() : ''));
        ADMIN_GRADE_MODULE_CACHE = { options: data.options || ADMIN_GRADE_MODULE_CACHE.options || {}, rows: data.items || data.grades || [], filters };
        if(contentArea){
            contentArea.innerHTML = adminRenderConsolidatedModulePage('grades', ADMIN_NEW_MODULE_PAGES.grades, data, data.items || data.grades || [], data.summary || {});
            bindAdminModuleForms('grades');
        }
    }catch(error){
        showToast(error.message || 'خطا در فیلتر ثبت کارنامه', 'error');
    }finally{showLoading(false); const lo=document.getElementById('loadingOverlay'); if(lo)lo.style.display='none';}
}

function adminGradeSelectByClass(){
    const classSelect=document.querySelector('#adminQuickGradeForm [name="class_id"]');
    const courseSelect=document.querySelector('#adminQuickGradeForm [name="course_id"]');
    if(!classSelect || !courseSelect) return;
    const classId=classSelect.value;
    Array.from(courseSelect.options).forEach(opt => {
        if(!opt.value) return;
        const courseClass=opt.getAttribute('data-class-id');
        opt.hidden = Boolean(classId) && classId !== 'all' && courseClass && courseClass !== classId;
    });
}
function adminGradeModeChanged(){
    const form=document.getElementById('adminQuickGradeForm');
    if(!form) return;
    const mode=form.grade_mode?.value || 'numeric';
    form.querySelectorAll('[data-grade-mode]').forEach(el=>el.style.display = el.dataset.gradeMode===mode ? '' : 'none');
}
async function adminDeleteGrade(id){
    if(!id || !confirm('این نمره حذف شود؟')) return;
    await fetchAPI(`/admin/modules/grades/${id}`, {method:'DELETE'});
    adminInvalidateReadCaches(['/admin/modules/grades', '/admin/modules/grades/options']);
    showToast('نمره حذف شد','success');
    loadAdminNewModulePage('grades');
}
async function adminApproveGrade(id){
    if(!id) return;
    await fetchAPI(`/admin/modules/grades/${id}/approve`, {method:'POST', body: JSON.stringify({reason:'تأیید مدیر'})});
    showToast('نمره تأیید شد','success');
    loadAdminNewModulePage('grades');
}
async function adminLockGrade(id){
    if(!id || !confirm('بعد از قفل کردن، نمره قابل ویرایش نیست. ادامه می‌دهید؟')) return;
    await fetchAPI(`/admin/modules/grades/${id}/lock`, {method:'POST', body: JSON.stringify({reason:'قفل نهایی'})});
    showToast('نمره قفل شد','success');
    loadAdminNewModulePage('grades');
}
async function adminOpenRealGradeHistory(id, studentName=''){
    let logs=[];
    if(id){
        const res=await fetchAPI(`/admin/modules/grades/${id}/history`).catch(()=>({logs:[]}));
        logs=res.logs||[];
    }
    if(!logs.length) return adminOpenGradeHistory(studentName);
    adminOpenModuleUtilityModal('تاریخچه تغییرات نمره' + (studentName?` - ${adminModuleEscape(studentName)}`:''), `<div class="admin-module-pro">${adminModuleTable(logs,[{label:'تاریخ و ساعت',render:r=>adminModuleEscape(r.created_at || '-')},{label:'تغییردهنده',render:r=>adminModuleEscape(r.changed_by_name || '-')},{label:'مقدار قبلی → جدید',render:r=>`${adminModuleEscape(r.previous_value || '-')} → ${adminModuleEscape(r.new_value || '-')}`},{label:'علت تغییر',key:'reason'}])}</div>`);
}
