async function adminApplyAdvancedGradeFilters(event){
    event?.preventDefault?.();
    const base=document.getElementById('adminGradesFilterForm');
    const params=new URLSearchParams(base ? new FormData(base) : undefined);
    const modalForm=event?.target;
    if(modalForm) Object.entries(Object.fromEntries(new FormData(modalForm).entries())).forEach(([k,v])=>{ if(v && v!=='all') params.set(k,v); });
    ADMIN_GRADE_MODULE_CACHE.filters=Object.fromEntries(params.entries());
    adminCloseModuleUtilityModal();
    showLoading(true);
    try{const data=await fetchAPI('/admin/modules/grades?'+params.toString()); ADMIN_GRADE_MODULE_CACHE={options:data.options||{},rows:data.items||data.grades||[],filters:Object.fromEntries(params.entries())}; document.getElementById('contentArea').innerHTML=adminRenderConsolidatedModulePage('grades',ADMIN_NEW_MODULE_PAGES.grades,data,data.items||data.grades||[],data.summary||{}); bindAdminModuleForms('grades');}catch(error){showToast(error.message||'خطا در فیلتر پیشرفته','error')}finally{showLoading(false); const lo=document.getElementById('loadingOverlay'); if(lo)lo.style.display='none';}
}
