function adminModuleSortTable(th){
    const table=th.closest('table'); if(!table)return;
    const index=[...th.parentNode.children].indexOf(th);
    const tbody=table.querySelector('tbody');
    const rows=[...tbody.querySelectorAll('tr')];
    const dir=th.dataset.dir==='asc'?'desc':'asc';
    th.dataset.dir=dir;
    rows.sort((a,b)=>{
        const A=(a.children[index]?.innerText||'').trim();
        const B=(b.children[index]?.innerText||'').trim();
        return dir==='asc'?A.localeCompare(B,'fa',{numeric:true}):B.localeCompare(A,'fa',{numeric:true});
    }).forEach(r=>tbody.appendChild(r));
}
function adminModuleInlineEditScore(btn){
    const row=btn.closest('tr'); const slot=row?.querySelector('.amp-score-slot'); if(!slot || slot.dataset.editing==='1')return;
    const score=slot.dataset.score||''; slot.dataset.editing='1';
    slot.innerHTML=`<input class="amp-input" type="number" min="0" max="20" step="0.25" value="${adminModuleEscape(score)}" style="width:82px;text-align:center">`;
    btn.innerHTML='<i class="fas fa-check"></i>'; btn.title='ذخیره سریع'; btn.onclick=function(){ const val=slot.querySelector('input')?.value||score; slot.dataset.score=val; slot.dataset.editing='0'; slot.innerHTML=adminModuleScoreCell(val); showToast('نمره به‌صورت سریع به‌روزرسانی شد','success'); };
}
