    const staffStatusOptions = [{value:'present',label:'حاضر'},{value:'absent',label:'غایب'},{value:'late',label:'تأخیر'},{value:'leave',label:'مرخصی'}];
    const disciplineTypeOptions = [{value:'warning',label:'تذکر'},{value:'unexcused_absence',label:'غیبت غیرموجه'},{value:'repeated_late',label:'تأخیر مکرر'},{value:'behavior',label:'رفتار نامناسب'},{value:'encouragement',label:'تشویقی'}];
    const severityOptions = [{value:'low',label:'کم'},{value:'medium',label:'متوسط'},{value:'high',label:'زیاد'}];
    let body='';
    if(kind==='student') body=`<form class="amp-modal-grid" id="adminQuickAttendanceForm"><div class="amp-field"><label>دانش‌آموز</label>${adminRenderSmartDropdown('student_id', studentOptions, '', 'انتخاب دانش‌آموز', 'جستجو در دانش‌آموزان...')}</div><div class="amp-field"><label>کلاس</label>${adminRenderSmartDropdown('class_id', classOptions, '', 'انتخاب کلاس', 'جستجو در کلاس‌ها...')}</div><div class="amp-field"><label>تاریخ شمسی</label><input class="amp-input" type="text" data-persian-date="true" name="date" value="${toPersianNumber(getTodayJalali())}" readonly required></div><div class="amp-field"><label>وضعیت</label>${adminRenderSmartDropdown('status', statusOptions, 'present', '', 'جستجو در وضعیت...')}</div><div class="amp-field full"><label>توضیحات</label><textarea class="amp-textarea" name="notes" placeholder="توضیحات اختیاری برای گزارش والدین یا پرونده دانش‌آموز..."></textarea></div><div class="full amp-modal-actions"><button class="amp-btn primary"><i class="fas fa-save"></i> ثبت حضور</button><button class="amp-btn white" type="button" onclick="adminCloseModuleUtilityModal()">انصراف</button></div></form>`;
    if(kind==='staff') body=`<div class="amp-modal-grid"><div class="amp-field"><label>پرسنل</label><input class="amp-input" placeholder="نام یا شناسه پرسنل"></div><div class="amp-field"><label>تاریخ شمسی</label><input class="amp-input" type="text" data-persian-date="true" value="${toPersianNumber(getTodayJalali())}" readonly></div><div class="amp-field"><label>ورود</label><input class="amp-input" type="time"></div><div class="amp-field"><label>خروج</label><input class="amp-input" type="time"></div><div class="amp-field full"><label>وضعیت</label>${adminRenderSmartDropdown('staff_status', staffStatusOptions, 'present', '', 'جستجو در وضعیت...')}</div><div class="full amp-modal-actions"><button class="amp-btn primary" type="button" onclick="adminCloseModuleUtilityModal();showToast('حضور پرسنل ثبت شد','success')"><i class="fas fa-save"></i> ثبت</button><button class="amp-btn white" type="button" onclick="adminCloseModuleUtilityModal()">انصراف</button></div></div>`;
    if(kind==='discipline') body=`<div class="amp-modal-grid"><div class="amp-field"><label>دانش‌آموز</label>${adminRenderSmartDropdown('student_id', studentOptions, '', 'انتخاب دانش‌آموز', 'جستجو در دانش‌آموزان...')}</div><div class="amp-field"><label>نوع مورد</label>${adminRenderSmartDropdown('discipline_type', disciplineTypeOptions, 'warning', '', 'جستجو در نوع مورد...')}</div><div class="amp-field"><label>تاریخ شمسی</label><input class="amp-input" type="text" data-persian-date="true" value="${toPersianNumber(getTodayJalali())}" readonly></div><div class="amp-field"><label>شدت / امتیاز</label>${adminRenderSmartDropdown('severity', severityOptions, 'medium', '', 'جستجو در شدت...')}</div><div class="amp-field full"><label>شرح مورد</label><textarea class="amp-textarea" placeholder="شرح کامل مورد انضباطی یا تشویقی برای ثبت در پرونده..."></textarea></div><div class="full amp-modal-actions"><button class="amp-btn primary" type="button" onclick="adminCloseModuleUtilityModal();showToast('مورد ثبت شد','success')"><i class="fas fa-save"></i> ثبت مورد</button><button class="amp-btn white" type="button" onclick="adminCloseModuleUtilityModal()">انصراف</button></div></div>`;
    adminOpenModuleUtilityModal(titles[kind]||'ثبت مورد', body, '860px');
    bindAdminModuleForms('attendance');
