// ============================================
// USER MANAGEMENT
// ============================================

let currentUserRole = 'all';
let searchTimeout;
let currentViewedUserId = null;
let quickAvatarUserId = null;
let pendingAddUserAvatarData = null;
let currentEditUserAvatarUrl = '';
let pendingEditUserAvatarData = null;
let pendingEditUserAvatarRemove = false;
const USER_CREDENTIALS_STORAGE_KEY = 'smartschool_recent_user_credentials';

function readRecentUserCredentials() {
    try {
        return JSON.parse(sessionStorage.getItem(USER_CREDENTIALS_STORAGE_KEY) || '{}');
    } catch {
        return {};
    }
}

function rememberUserCredentials(userId, credentials) {
    if (!userId || !credentials) return;
    const allCredentials = readRecentUserCredentials();
    allCredentials[String(userId)] = {
        ...(allCredentials[String(userId)] || {}),
        ...credentials,
        savedAt: Date.now()
    };
    sessionStorage.setItem(USER_CREDENTIALS_STORAGE_KEY, JSON.stringify(allCredentials));
}

function getRememberedUserCredentials(userId) {
    const allCredentials = readRecentUserCredentials();
    return allCredentials[String(userId)] || null;
}

function generateAutomaticPassword() {
    const digits = new Uint32Array(1);
    if (window.crypto?.getRandomValues) {
        window.crypto.getRandomValues(digits);
    } else {
        digits[0] = Math.floor(Math.random() * 1000000);
    }
    return `Sch${String(digits[0] % 1000000).padStart(6, '0')}`;
}

async function buildUniqueUsername(firstName, lastName) {
    let base = buildSuggestedUsername(firstName, lastName) || `user${Math.floor(1000 + Math.random() * 9000)}`;
    base = base.slice(0, 80);

    try {
        const response = await fetchAPI(`/admin/users?search=${encodeURIComponent(base)}&page=1&limit=200`);
        const used = new Set((response.users || []).map(user => String(user.username || '').toLowerCase()));
        if (!used.has(base.toLowerCase())) return base;

        let suffix = 2;
        while (used.has(`${base}${suffix}`.toLowerCase())) suffix += 1;
        return `${base}${suffix}`;
    } catch (error) {
        console.warn('Username uniqueness check failed:', error);
        return `${base}${Math.floor(100 + Math.random() * 900)}`;
    }
}

function copyCredentialValue(value, label = 'مقدار') {
    const text = String(value || '');
    if (!text) return;
    navigator.clipboard?.writeText(text)
        .then(() => showToast(`${label} کپی شد`, 'success'))
        .catch(() => showToast('امکان کپی خودکار وجود ندارد', 'warning'));
}

