function toggleUserFields() {
    const role = document.getElementById('userRole')?.value || 'student';
    const isStudent = role === 'student';
    const parentFields = document.getElementById('parentFields');
    const classGroup = document.getElementById('userClassGroup');
    const sectionTitle = document.getElementById('primaryUserSectionTitle');
    const nationalIdLabel = document.getElementById('primaryNationalIdLabel');
    const nationalIdRequired = document.getElementById('primaryNationalIdRequired');

    if (parentFields) parentFields.style.display = isStudent ? 'block' : 'none';
    if (classGroup) classGroup.style.display = isStudent ? 'block' : 'none';
    document.querySelectorAll('.teacher-profile-field').forEach(field => { field.style.display = role === 'teacher' ? 'block' : 'none'; });
    if (sectionTitle) sectionTitle.textContent = isStudent ? 'اطلاعات دانش‌آموز' : (role === 'teacher' ? 'اطلاعات معلم' : 'اطلاعات کاربر');
    if (nationalIdLabel) nationalIdLabel.textContent = isStudent ? 'کد ملی دانش‌آموز' : 'کد ملی کاربر';
    if (nationalIdRequired) nationalIdRequired.style.display = (isStudent || role === 'parent') ? 'inline' : 'none';
}

// بررسی وجود والد با کد ملی
async function checkParentExists(nationalId) {
    try {
        const response = await fetchAPI(`/admin/users?role=parent&search=${nationalId}`);
        return response.users && response.users.length > 0 ? response.users[0] : null;
    } catch {
        return null;
    }
}

// ایجاد والد جدید به صورت خودکار
async function createParentAutomatically(parentData) {
    try {
        const parentNameParts = normalizePersianName(parentData.name || 'والد کاربر').split(' ');
        const parentFirstName = parentNameParts.shift() || 'والد';
        const parentLastName = parentNameParts.join(' ') || 'کاربر';
        const username = await buildUniqueUsername(parentFirstName, parentLastName);
        const password = generateAutomaticPassword();

        const newParent = {
            username,
            password,
            name: parentData.name || 'والد کاربر',
            role: 'parent',
            phone: parentData.phone || '',
            email: parentData.email || '',
            national_id: parentData.nationalId,
            status: 'active'
        };

        const response = await fetchAPI('/admin/users', { method: 'POST', body: JSON.stringify(newParent) });

        if (response.success) {
            return {
                userId: response.user_id,
                credentials: {
                    username: response.username || username,
                    password,
                    name: newParent.name,
                    role: 'parent'
                }
            };
        }
        return null;
    } catch (error) {
        console.error('Error creating parent:', error);
        showToast('خطا در ایجاد حساب والدین', 'error');
        return null;
    }
}

