async function classManagerOpenDetails(id) {
    showLoading(true);
    try {
        const response = await fetchAPI(`/admin/classes/${id}`);
        const item = response.class || {};
        const students = Array.isArray(response.students) ? response.students : [];
        const courses = Array.isArray(response.courses) ? response.courses : [];
        const stateItem = (window.classManagerState?.classes || []).find(c => Number(c.id) === Number(id)) || {};
        const assignedCourses = courses.filter(course => String(course.teacher_name || '').trim()).length;
        document.getElementById('cmDetailsSubtitle').textContent = `${item.name || 'کلاس'} · پایه ${classManagerStatNumber(item.grade || 0)}`;
        document.getElementById('cmDetailsBody').innerHTML = `
            <div class="cm-details-grid" style="margin-bottom:.9rem">
                <div class="cm-detail"><i class="fas fa-graduation-cap"></i><small>پایه</small><strong>${classManagerStatNumber(item.grade || 0)}</strong></div>
                <div class="cm-detail"><i class="fas fa-user-graduate"></i><small>دانش‌آموزان</small><strong>${classManagerStatNumber(students.length)} نفر</strong></div>
                <div class="cm-detail"><i class="fas fa-chair"></i><small>ظرفیت</small><strong>${classManagerStatNumber(item.capacity || 0)} نفر</strong></div>
                <div class="cm-detail"><i class="fas fa-book-open"></i><small>دروس دارای معلم</small><strong>${classManagerStatNumber(assignedCourses)} از ${classManagerStatNumber(courses.length)}</strong></div>
            </div>
            ${item.main_teacher_name ? `<div class="cm-president-card"><span class="cm-president-icon"><i class="fas fa-crown"></i></span><div><small>رئیس انجمن معلمان</small><strong>${escapeHtml(item.main_teacher_name)}</strong></div></div>` : ''}
            <div class="cm-section"><div class="cm-section-title"><i class="fas fa-users"></i> دانش‌آموزان کلاس</div>${students.length ? `<div class="cm-list">${students.map(student => `<div class="cm-list-row"><div class="cm-list-main"><span class="cm-list-avatar">${escapeHtml((student.name || 'د').trim().charAt(0))}</span><div><div class="cm-list-name">${escapeHtml(student.name || 'بدون نام')}</div><div class="cm-list-sub">${escapeHtml(student.username || student.phone || 'اطلاعات تماس ثبت نشده')}</div></div></div><i class="fas fa-chevron-left" style="color:#cbd5e1"></i></div>`).join('')}</div>` : '<div class="cm-empty" style="padding:1.5rem"><p>هنوز دانش‌آموزی در این کلاس ثبت نشده است.</p></div>'}</div>
            <div class="cm-section"><div class="cm-section-title"><i class="fas fa-book"></i> دروس و معلمان</div>${courses.length ? `<div class="cm-list">${courses.map(course => `<div class="cm-list-row"><div class="cm-list-main"><span class="cm-list-avatar"><i class="fas fa-book"></i></span><div><div class="cm-list-name">${escapeHtml(course.name || 'درس')}</div><div class="cm-list-sub">معلم: ${escapeHtml(course.teacher_name || 'تعیین نشده')}</div></div></div><span class="cm-status ${course.teacher_name ? 'active' : 'inactive'}">${course.teacher_name ? 'تخصیص داده شده' : 'بدون معلم'}</span></div>`).join('')}</div>` : `<div class="cm-empty" style="padding:1.5rem"><p>برای این کلاس هنوز درسی ثبت نشده است.</p></div>`}</div>
            ${stateItem.teachers_name ? `<div class="cm-section"><div class="cm-section-title"><i class="fas fa-chalkboard-user"></i> همه معلمان مرتبط</div><div class="cm-teacher-list">${String(stateItem.teachers_name).split('،').map(name=>`<span class="cm-teacher-chip"><i class="fas fa-user"></i>${escapeHtml(name.trim())}</span>`).join('')}</div></div>` : ''}`;
        classManagerOpenModal('cmDetailsModal');
    } catch (error) { showToast(error.message || 'خطا در دریافت جزئیات کلاس', 'error'); }
    finally { showLoading(false); }
}

async function classManagerOpenTeachers(id) {
    const state = window.classManagerState;
    const item = (state?.classes || []).find(c => Number(c.id) === Number(id));
    document.getElementById('cmTeachersClassId').value = id;
    document.getElementById('cmTeachersSubtitle').textContent = `کلاس ${item?.name || id} · انتخاب معلم برای هر درس`;
    document.getElementById('cmTeacherRows').innerHTML = '';
    showLoading(true);
    try {
        const response = await fetchAPI(`/admin/classes/${id}/teachers`);
        const courses = Array.isArray(response.courses) ? response.courses : [];
        const assignments = Array.isArray(response.assignments)
            ? response.assignments
            : (Array.isArray(response.teachers) ? response.teachers : []).map(teacher => ({
                teacher_id: teacher.teacher_id || teacher.id,
                teacher_name: teacher.teacher_name || teacher.name,
                course_id: teacher.course_id || ''
            }));
        state.teacherCourses = courses;
        state.currentTeacherAssignments = assignments;
        if (!courses.length) {
            document.getElementById('cmTeacherRows').innerHTML = `<div class="cm-empty" style="padding:1.6rem"><div class="cm-empty-icon" style="width:58px;height:58px"><i class="fas fa-book"></i></div><h4>درسی برای این کلاس ثبت نشده است</h4><p>ابتدا از صفحه مدیریت دروس، درس‌های این کلاس را ایجاد کنید.</p></div>`;
        } else if (assignments.length) {
            assignments.forEach(assignment => classManagerAddTeacherRow(assignment));
        } else {
            classManagerAddTeacherRow();
        }
        classManagerOpenModal('cmTeachersModal');
    } catch (error) { showToast(error.message || 'خطا در دریافت دروس و معلمان کلاس', 'error'); }
    finally { showLoading(false); }
}

function classManagerAddTeacherRow(assignment = null) {
    const state = window.classManagerState;
    const host = document.getElementById('cmTeacherRows');
    if (!state || !host) return;
    const courses = Array.isArray(state.teacherCourses) ? state.teacherCourses : [];
    if (!courses.length) return showToast('برای این کلاس هنوز درسی ثبت نشده است', 'warning');
    const rowId = `cmTeacherRow${++state.teacherRowCounter}`;
    const teacherId = String(assignment?.teacher_id || assignment?.id || '');
    const courseId = String(assignment?.course_id || '');
    const teacherOptions = [{value:'',label:'انتخاب معلم'},...state.teachers.map(item=>({value:String(item.id),label:item.name}))];
    const courseOptions = [{value:'',label:'انتخاب درس'},...courses.map(item=>({value:String(item.id),label:item.name}))];
    host.insertAdjacentHTML('beforeend', `
        <div class="cm-teacher-row" id="${rowId}">
            <div class="cm-teacher-cell">
                <label><i class="fas fa-user-tie"></i> معلم</label>
                ${classManagerSelectMarkup(`${rowId}Teacher`, teacherOptions, teacherId, 'fa-user-tie')}
            </div>
            <div class="cm-teacher-cell cm-course-select">
                <label><i class="fas fa-book-open"></i> درس</label>
                ${classManagerSelectMarkup(`${rowId}Course`, courseOptions, courseId, 'fa-book-open')}
            </div>
            <button class="cm-row-delete" type="button" onclick="classManagerRemoveTeacherRow('${rowId}')" title="حذف این اتصال"><i class="fas fa-trash"></i></button>
        </div>`);
}

function classManagerRemoveTeacherRow(rowId) {
    const rows = document.querySelectorAll('#cmTeacherRows .cm-teacher-row');
    if (rows.length <= 1) {
        const row = document.getElementById(rowId);
        row?.querySelectorAll('.cm-select').forEach(select => {
            const first = select.querySelector('.cm-select-option');
            if (first) classManagerChooseSelect(select.id, first);
        });
        return;
    }
    document.getElementById(rowId)?.remove();
}

async function classManagerSaveTeachers() {
    const classId = Number(document.getElementById('cmTeachersClassId')?.value || 0);
    const assignments = [];
    let hasIncompleteRow = false;
    document.querySelectorAll('#cmTeacherRows .cm-teacher-row').forEach(row => {
        const teacherId = row.querySelector('input[id$="TeacherValue"]')?.value || '';
        const courseId = row.querySelector('input[id$="CourseValue"]')?.value || '';
        if ((teacherId && !courseId) || (!teacherId && courseId)) hasIncompleteRow = true;
        if (teacherId && courseId) {
            const key = `${courseId}:${teacherId}`;
            if (!assignments.some(item => item.key === key)) {
                assignments.push({ key, course_id: Number(courseId), teacher_id: Number(teacherId), role: 'main' });
            }
        }
    });
    if (hasIncompleteRow) return showToast('برای هر ردیف، هم معلم و هم درس را انتخاب کنید', 'error');
    if (!assignments.length) return showToast('حداقل یک معلم و درس انتخاب کنید', 'error');
    showLoading(true);
    try {
        await fetchAPI(`/admin/classes/${classId}/teachers`, {
            method: 'PUT',
            body: JSON.stringify({ assignments: assignments.map(({key, ...item}) => item) })
        });
        showToast('معلم هر درس با موفقیت ذخیره شد', 'success');
        classManagerCloseModal('cmTeachersModal');
        await loadClasses();
    } catch (error) { showToast(error.message || 'خطا در ذخیره معلمان دروس کلاس', 'error'); }
    finally { showLoading(false); }
}

function classManagerAskDelete(id) {
    const item = (window.classManagerState?.classes || []).find(c => Number(c.id) === Number(id));
    window.classManagerState.deleteTargetId = id;
    document.getElementById('cmDeleteText').textContent = `کلاس «${item?.name || id}» غیرفعال و از فهرست عملیاتی مدرسه حذف می‌شود. اطلاعات مرتبط به‌صورت ایمن حفظ خواهند شد.`;
    classManagerOpenModal('cmDeleteModal');
}

async function classManagerDeleteConfirmed() {
    const id = Number(window.classManagerState?.deleteTargetId || 0);
    if (!id) return;
    showLoading(true);
    try {
        await fetchAPI(`/admin/classes/${id}`, { method: 'DELETE' });
        showToast('کلاس با موفقیت حذف شد', 'success');
        classManagerCloseModal('cmDeleteModal');
        await loadClasses();
    } catch (error) { showToast(error.message || 'خطا در حذف کلاس', 'error'); }
    finally { showLoading(false); }
}

