function debouncedClassSearch() {
    clearTimeout(classSearchTimeout);
    classSearchTimeout = setTimeout(() => {
        const search = document.getElementById('searchClass')?.value || '';
        const filtered = allClassesData.filter(c => 
            c.name.toLowerCase().includes(search.toLowerCase()) || 
            c.grade.toString().includes(search)
        );
        renderClassesGrid(filtered);
    }, 500);
}

function renderClassesGrid(classes) {
    const container = document.getElementById('classesGrid');
    if (!container) return;
    
    if (classes.length === 0) {
        container.innerHTML = `<div class="empty-state">...</div>`;
    } else {
        container.innerHTML = classes.map(c => {
            const occupancy = c.capacity ? Math.round((c.student_count / c.capacity) * 100) : 0;
            const statusClass = c.status === 'active' ? 'فعال' : 'غیرفعال';
            const statusColor = c.status === 'active' ? '#10b981' : '#ef4444';
            
            // دریافت نام معلمانی که در این کلاس تدریس می‌کنند
            const teachersList = c.teachers_name ? c.teachers_name.split('، ') : [];
            const teachersHtml = teachersList.length > 0 ? 
                teachersList.map(t => `<span class="teacher-tag"><i class="fas fa-chalkboard-user"></i> ${escapeHtml(t)}</span>`).join('') :
                '<span class="no-teacher"><i class="fas fa-info-circle"></i> معلمی تعیین نشده</span>';
            
            return `
                <div class="class-item">
                    <div class="class-header">
                        <div class="class-name">
                            <i class="fas fa-door-open"></i>
                            ${escapeHtml(c.name)}
                        </div>
                        <div class="class-badge" style="background: ${statusColor}20; color: ${statusColor};">
                            <i class="fas ${c.status === 'active' ? 'fa-check-circle' : 'fa-ban'}"></i> ${statusClass}
                        </div>
                    </div>
                    <div class="class-body">
                        <div class="class-info">
                            <div class="class-grade">
                                <i class="fas fa-graduation-cap"></i>
                                پایه ${c.grade}
                            </div>
                            <div class="class-capacity">
                                <i class="fas fa-users"></i>
                                ${c.student_count || 0} / ${c.capacity || 30} نفر
                            </div>
                        </div>
                        <div class="class-progress">
                            <div class="progress-label">
                                <span>درصد پرشدگی</span>
                                <span>${occupancy}%</span>
                            </div>
                            <div class="progress-bar">
                                <div class="progress-fill" style="width: ${occupancy}%"></div>
                            </div>
                        </div>
                        <div class="class-teachers">
                            <div class="teachers-title">
                                <i class="fas fa-chalkboard-user"></i> معلمان این کلاس:
                            </div>
                            <div class="teachers-list">
                                ${teachersHtml}
                            </div>
                        </div>
                    <div class="class-actions">
                        <button class="action-btn edit" onclick="window.editClass(${c.id})">
                            <i class="fas fa-edit"></i> ویرایش
                        </button>
                        <button class="action-btn delete" onclick="window.deleteClass(${c.id})">
                            <i class="fas fa-trash"></i> حذف
                        </button>
                    </div>
                    </div>
                </div>
            `;
        }).join('');
    }
}

function openAddClassModal() {
    document.getElementById('className').value = '';
    document.getElementById('classGrade').value = '';
    document.getElementById('classCapacity').value = '30';
    openModal('addClassModal');
}

async function saveClass() {
    const data = {
        name: document.getElementById('className').value.trim(),
        grade: parseInt(document.getElementById('classGrade').value) || 1,
        capacity: parseInt(document.getElementById('classCapacity').value) || 30
    };
    
    if (!data.name) {
        showToast('نام کلاس الزامی است', 'error');
        return;
    }
    
    showLoading(true);
    try {
        await fetchAPI('/admin/classes', { method: 'POST', body: JSON.stringify(data) });
        showToast('کلاس با موفقیت اضافه شد', 'success');
        closeModal('addClassModal');
        await loadClasses();
    } catch (error) {
        showToast(error.message || 'خطا در ذخیره', 'error');
    } finally {
        showLoading(false);
    }
}

async function editClass(id) {
    try {
        // دریافت اطلاعات کلاس
        const response = await fetchAPI(`/admin/classes/${id}`);
        const classData = response.class;
        if (!classData) return;
        
        // دریافت لیست معلمان برای سلکت
        const teachersRes = await fetchAPI('/admin/teachers').catch(() => ({ teachers: [] }));
        const teachers = teachersRes.teachers || [];
        
        // پر کردن فیلدهای مودال
        document.getElementById('editClassId').value = classData.id;
        document.getElementById('editClassName').value = classData.name;
        document.getElementById('editClassGrade').value = classData.grade;
        document.getElementById('editClassCapacity').value = classData.capacity || 30;
        document.getElementById('editClassStatus').value = classData.status || 'active';
        
        // ساخت آپشن‌های انتخاب معلم
        const teacherSelect = document.getElementById('editClassMainTeacher');
        if (teacherSelect) {
            let options = '<option value="">بدون معلم</option>';
            teachers.forEach(teacher => {
                const selected = teacher.id == classData.main_teacher_id ? 'selected' : '';
                options += `<option value="${teacher.id}" ${selected}>${escapeHtml(teacher.name)}</option>`;
            });
            teacherSelect.innerHTML = options;
        }
        
        openModal('editClassModal');
    } catch (error) {
        console.error('Error editClass:', error);
        showToast('خطا در دریافت اطلاعات کلاس', 'error');
    }
}

async function updateClass() {
    const id = document.getElementById('editClassId').value;
    
    const name = document.getElementById('editClassName').value.trim();
    const grade = parseInt(document.getElementById('editClassGrade').value);
    const capacity = parseInt(document.getElementById('editClassCapacity').value);
    const main_teacher_id = document.getElementById('editClassMainTeacher')?.value || null;
    const status = document.getElementById('editClassStatus').value;
    
    const data = {
        name: name,
        grade: grade,
        capacity: capacity,
        main_teacher_id: main_teacher_id,
        status: status
    };
    
    if (!name) {
        showToast('نام کلاس الزامی است', 'error');
        return;
    }
    
    showLoading(true);
    try {
        await fetchAPI(`/admin/classes/${id}`, { method: 'PUT', body: JSON.stringify(data) });
        showToast('کلاس با موفقیت ویرایش شد', 'success');
        closeModal('editClassModal');
        await loadClasses();
    } catch (error) {
        console.error('Update class error:', error);
        showToast(error.message || 'خطا در ویرایش', 'error');
    } finally {
        showLoading(false);
    }
}

async function deleteClass(id) {
    if (!confirm('آیا از حذف این کلاس مطمئن هستید؟ این عملیات قابل بازگشت نیست!')) return;
    
    showLoading(true);
    try {
        await fetchAPI(`/admin/classes/${id}`, { method: 'DELETE' });
        showToast('کلاس با موفقیت حذف شد', 'success');
        await loadClasses();
    } catch (error) {
        showToast(error.message || 'خطا در حذف', 'error');
    } finally {
        showLoading(false);
    }
}

