let currentClassId = null;

function openClassTeachersModal(classId, className) {
    currentClassId = classId;
    document.getElementById('teacherClassId').value = classId;
    document.getElementById('teacherClassName').innerHTML = className;
    
    // ریست فرم معلمان
    const container = document.getElementById('teacherSelectContainer');
    if (container) {
        container.innerHTML = `
            <div class="teacher-row">
                <select name="teacher_id[]" class="teacher-select form-control">
                    <option value="">انتخاب معلم</option>
                    ${(window.classListTeachers || []).map(t => `<option value="${t.id}">${escapeHtml(t.name)}</option>`).join('')}
                </select>
                <select name="teacher_role[]" class="teacher-role form-control">
                    <option value="main">اصلی</option>
                    <option value="assistant">کمک</option>
                    <option value="substitute">جانشین</option>
                </select>
                <button type="button" class="btn-icon-sm" onclick="removeTeacherRow(this)" style="display: none;">🗑️</button>
            </div>
        `;
    }
    
    // بارگذاری معلمان موجود این کلاس
    loadClassTeachers(classId);
    
    openModal('classTeachersModal');
}

async function loadClassTeachers(classId) {
    try {
        const response = await fetchAPI(`/admin/classes/${classId}/teachers`).catch(() => ({ teachers: [] }));
        const teachers = response.teachers || [];
        
        if (teachers.length > 0 && window.classListTeachers) {
            const container = document.getElementById('teacherSelectContainer');
            if (container) {
                container.innerHTML = '';
                teachers.forEach(teacher => {
                    const row = document.createElement('div');
                    row.className = 'teacher-row';
                    row.innerHTML = `
                        <select name="teacher_id[]" class="teacher-select form-control">
                            <option value="">انتخاب معلم</option>
                            ${window.classListTeachers.map(t => `<option value="${t.id}" ${t.id == teacher.id ? 'selected' : ''}>${escapeHtml(t.name)}</option>`).join('')}
                        </select>
                        <select name="teacher_role[]" class="teacher-role form-control">
                            <option value="main" ${teacher.role === 'main' ? 'selected' : ''}>اصلی</option>
                            <option value="assistant" ${teacher.role === 'assistant' ? 'selected' : ''}>کمک</option>
                            <option value="substitute" ${teacher.role === 'substitute' ? 'selected' : ''}>جانشین</option>
                        </select>
                        <button type="button" class="btn-icon-sm" onclick="removeTeacherRow(this)">🗑️</button>
                    `;
                    container.appendChild(row);
                });
            }
        }
    } catch (error) {
        console.error('Error loading class teachers:', error);
    }
}

