async function saveClassTeachers() {
    const classId = document.getElementById('teacherClassId').value;
    const teacherRows = document.querySelectorAll('#teacherSelectContainer .teacher-row');
    const teachers = [];
    
    teacherRows.forEach(row => {
        const teacherId = row.querySelector('.teacher-select')?.value;
        const role = row.querySelector('.teacher-role')?.value;
        if (teacherId) {
            teachers.push({ id: teacherId, role: role || 'assistant' });
        }
    });
    
    if (teachers.length === 0) {
        showToast('حداقل یک معلم باید انتخاب شود', 'error');
        return;
    }
    
    showLoading(true);
    try {
        await fetchAPI(`/admin/classes/${classId}/teachers`, {
            method: 'PUT',
            body: JSON.stringify({ teachers: teachers })
        });
        showToast('معلمان کلاس با موفقیت به‌روزرسانی شدند', 'success');
        closeModal('classTeachersModal');
        await loadClasses();
    } catch (error) {
        showToast(error.message || 'خطا در ذخیره معلمان', 'error');
    } finally {
        showLoading(false);
    }
}
