// ============================================
// توابع برنامه هفتگی و زنگ‌ها
// ============================================

function getTodayPeriods(weekday) {
    // دریافت برنامه امروز از دیتابیس یا آرایه پیش‌فرض
    const periods = weekSchedule.filter(s => s.day === weekday);
    
    if (periods.length === 0) {
        // زنگ‌های پیش‌فرض اگر برنامه‌ای ثبت نشده باشد
        return [
            { id: 'first', name: 'زنگ اول', time: '08:00 - 09:30', teacher: null, course: null },
            { id: 'second', name: 'زنگ دوم', time: '09:45 - 11:15', teacher: null, course: null },
            { id: 'third', name: 'زنگ سوم', time: '11:30 - 13:00', teacher: null, course: null },
            { id: 'fourth', name: 'زنگ چهارم', time: '13:30 - 15:00', teacher: null, course: null }
        ];
    }
    return periods;
}

function updatePeriodTabs(periods) {
    const container = document.getElementById('periodTabs');
    if (!container) return;
    
    container.innerHTML = periods.map((period, index) => {
        const isActive = index === 0 ? 'active' : '';
        return `
            <button class="period-tab ${isActive}" data-period="${period.id}" onclick="selectPeriod('${period.id}')">
                <i class="fas fa-bell"></i> ${period.name}
                <small style="font-size: 0.65rem;">${period.time || ''}</small>
            </button>
        `;
    }).join('');
    
    // انتخاب زنگ اول به صورت پیش‌فرض
    if (periods.length > 0) {
        selectPeriod(periods[0].id);
    }
}

function selectPeriod(periodId) {
    currentPeriod = periodId;
    
    // بروزرسانی کلاس active تب‌ها
    document.querySelectorAll('.period-tab').forEach(tab => {
        tab.classList.remove('active');
        if (tab.getAttribute('data-period') === periodId) {
            tab.classList.add('active');
        }
    });
    
    // دریافت اطلاعات زنگ انتخاب شده
    const weekday = weekDaysEnglish[new Date(selectedDate ? new Date(selectedDate).getDay() : new Date().getDay())];
    const periods = getTodayPeriods(weekday);
    currentPeriodInfo = periods.find(p => p.id === periodId);
    
    // بروزرسانی اطلاعات زنگ
    const infoContainer = document.getElementById('periodInfo');
    if (infoContainer && currentPeriodInfo) {
        infoContainer.innerHTML = `
            <div class="teacher-info">
                <i class="fas fa-chalkboard-user"></i>
                <span>معلم: ${currentPeriodInfo.teacher ? escapeHtml(currentPeriodInfo.teacher) : 'تعیین نشده'}</span>
            </div>
            <div class="teacher-info">
                <i class="fas fa-book"></i>
                <span>درس: ${currentPeriodInfo.course ? escapeHtml(currentPeriodInfo.course) : 'تعیین نشده'}</span>
            </div>
            <div class="teacher-info">
                <i class="fas fa-clock"></i>
                <span>ساعت: ${currentPeriodInfo.time || 'نامشخص'}</span>
            </div>
        `;
    }
    
    // بارگذاری مجدد جدول حضور و غیاب برای این زنگ
    loadAttendanceTable();
}

function updateDateDisplay(date) {
    const dateElement = document.getElementById('currentDate');
    if (dateElement) {
        try {
            let persianDate = '';
            if (typeof moment !== 'undefined') {
                persianDate = moment(date).format('jYYYY/jMM/jDD');
            } else {
                persianDate = new Date(date).toLocaleDateString('fa-IR');
            }
            dateElement.innerHTML = `${persianDate}`;
        } catch (e) {
            dateElement.innerHTML = date;
        }
    }
}

function changeDate(days) {
    if (!selectedDate) {
        selectedDate = new Date().toISOString().split('T')[0];
    }
    const newDate = new Date(selectedDate);
    newDate.setDate(newDate.getDate() + days);
    selectedDate = newDate.toISOString().split('T')[0];
    
    updateDateDisplay(selectedDate);
    
    // بروزرسانی زنگ‌ها بر اساس روز جدید
    const newWeekday = weekDaysEnglish[newDate.getDay()];
    const newPeriods = getTodayPeriods(newWeekday);
    updatePeriodTabs(newPeriods);
    
    loadAttendanceTable();
}

function goToToday() {
    selectedDate = new Date().toISOString().split('T')[0];
    updateDateDisplay(selectedDate);
    
    const todayWeekday = weekDaysEnglish[new Date().getDay()];
    const todayPeriods = getTodayPeriods(todayWeekday);
    updatePeriodTabs(todayPeriods);
    
    loadAttendanceTable();
}

// ============================================
// توابع حضور و غیاب
// ============================================

function debouncedAttendanceSearch() {
    clearTimeout(attendanceSearchTimeout);
    attendanceSearchTimeout = setTimeout(() => loadAttendanceTable(), 500);
}

async function loadAttendanceTable() {
    const classId = document.getElementById('attendanceClass')?.value;
    const search = document.getElementById('attendanceSearch')?.value || '';
    const date = selectedDate || new Date().toISOString().split('T')[0];
    const period = currentPeriod;
    
    if (!classId) {
        document.getElementById('attendanceTableBody').innerHTML = '<tr><td colspan="6" class="empty-state">لطفاً کلاس را انتخاب کنید</div>';
        resetStats();
        return;
    }
    
    showLoading(true);
    try {
        let url = `/admin/attendance?class_id=${classId}&date=${date}&period=${period}&search=${encodeURIComponent(search)}`;
        
        const response = await fetchAPI(url);
        const students = response.students || [];
        const stats = response.stats || {};
        currentAttendanceData = students;
        
        // بروزرسانی آمار
        document.getElementById('statPresent').textContent = toPersianNumber(stats.present || 0);
        document.getElementById('statAbsent').textContent = toPersianNumber(stats.absent || 0);
        document.getElementById('statLate').textContent = toPersianNumber(stats.late || 0);
        document.getElementById('statExcused').textContent = toPersianNumber(stats.excused || 0);
        
        const total = (stats.present || 0) + (stats.absent || 0) + (stats.late || 0) + (stats.excused || 0);
        const rate = total > 0 ? Math.round(((stats.present || 0) / total) * 100) : 0;
        document.getElementById('statRate').textContent = `${rate}%`;
        
        const tbody = document.getElementById('attendanceTableBody');
        if (students.length === 0) {
            tbody.innerHTML = '<tr><td colspan="6" class="empty-state">دانش‌آموزی یافت نشد</div>';
        } else {
            // بارگذاری وضعیت‌های ذخیره شده موقت
            const tempKey = `${date}_${period}_${classId}`;
            if (!tempAttendanceStatus[tempKey]) tempAttendanceStatus[tempKey] = {};
            
            students.forEach(student => {
                if (tempAttendanceStatus[tempKey][student.id] === undefined) {
                    tempAttendanceStatus[tempKey][student.id] = student.status;
                }
            });
            
            tbody.innerHTML = students.map((student, index) => {
                const currentStatus = tempAttendanceStatus[tempKey][student.id] || student.status;
                const statusClass = currentStatus;
                const statusText = currentStatus === 'present' ? 'حاضر' : (currentStatus === 'absent' ? 'غایب' : (currentStatus === 'late' ? 'تأخیر' : 'موجه'));
                const statusIcon = currentStatus === 'present' ? 'fa-check-circle' : (currentStatus === 'absent' ? 'fa-times-circle' : (currentStatus === 'late' ? 'fa-clock' : 'fa-shield-alt'));
                
                return `
                    <tr data-student-id="${student.id}">
                        <td>${index + 1}</div>
                        <td>
                            <div class="student-cell">
                                <div class="student-avatar">${student.name.charAt(0)}</div>
                                <strong>${escapeHtml(student.name)}</strong>
                            </div>
                        </div>
                        <td>${student.class_name}</div>
                        <td>
                            <span class="status-pill ${statusClass}">
                                <i class="fas ${statusIcon}"></i> ${statusText}
                            </span>
                        </div>
                        <td>
                            <div class="status-toggle-group">
                                <button class="status-toggle-btn present ${currentStatus === 'present' ? 'active' : ''}" onclick="setStudentStatusTemp(${student.id}, 'present', this)">
                                    <i class="fas fa-check-circle"></i> <span>حاضر</span>
                                </button>
                                <button class="status-toggle-btn absent ${currentStatus === 'absent' ? 'active' : ''}" onclick="setStudentStatusTemp(${student.id}, 'absent', this)">
                                    <i class="fas fa-times-circle"></i> <span>غایب</span>
                                </button>
                                <button class="status-toggle-btn late ${currentStatus === 'late' ? 'active' : ''}" onclick="setStudentStatusTemp(${student.id}, 'late', this)">
                                    <i class="fas fa-clock"></i> <span>تأخیر</span>
                                </button>
                                <button class="status-toggle-btn excused ${currentStatus === 'excused' ? 'active' : ''}" onclick="setStudentStatusTemp(${student.id}, 'excused', this)">
                                    <i class="fas fa-shield-alt"></i> <span>موجه</span>
                                </button>
                            </div>
                        </div>
                        <td>
                            <input type="text" class="note-input" id="note_${student.id}_${period}" value="${escapeHtml(student.note || '')}" placeholder="توضیحات...">
                        </div>
                    </tr>
                `;
            }).join('');
        }
        
    } catch (error) {
        console.error('Error loadAttendanceTable:', error);
        showToast('خطا در بارگذاری اطلاعات', 'error');
    }
    showLoading(false);
}

function setStudentStatusTemp(studentId, status, btnElement) {
    const classId = document.getElementById('attendanceClass')?.value;
    const date = selectedDate || new Date().toISOString().split('T')[0];
    const period = currentPeriod;
    const tempKey = `${date}_${period}_${classId}`;
    
    if (!tempAttendanceStatus[tempKey]) tempAttendanceStatus[tempKey] = {};
    tempAttendanceStatus[tempKey][studentId] = status;
    
    // بروزرسانی UI دکمه‌ها
    const row = btnElement.closest('tr');
    const buttons = row.querySelectorAll('.status-toggle-btn');
    buttons.forEach(btn => {
        btn.classList.remove('active');
        if (btn.classList.contains(status)) {
            btn.classList.add('active');
        }
    });
    
    // بروزرسانی نمایش وضعیت در ستون وضعیت فعلی
    const statusCell = row.querySelector('.status-pill');
    if (statusCell) {
        const statusText = status === 'present' ? 'حاضر' : (status === 'absent' ? 'غایب' : (status === 'late' ? 'تأخیر' : 'موجه'));
        const statusIcon = status === 'present' ? 'fa-check-circle' : (status === 'absent' ? 'fa-times-circle' : (status === 'late' ? 'fa-clock' : 'fa-shield-alt'));
        statusCell.className = `status-pill ${status}`;
        statusCell.innerHTML = `<i class="fas ${statusIcon}"></i> ${statusText}`;
    }
    
    // بروزرسانی آمار موقت
    updateTempStats();
}

function markAllAs(status) {
    const classId = document.getElementById('attendanceClass')?.value;
    if (!classId) {
        showToast('لطفاً ابتدا کلاس را انتخاب کنید', 'warning');
        return;
    }
    
    const date = selectedDate || new Date().toISOString().split('T')[0];
    const period = currentPeriod;
    const tempKey = `${date}_${period}_${classId}`;
    
    if (!tempAttendanceStatus[tempKey]) tempAttendanceStatus[tempKey] = {};
    
    currentAttendanceData.forEach(student => {
        tempAttendanceStatus[tempKey][student.id] = status;
    });
    
    // بروزرسانی UI جدول
    const rows = document.querySelectorAll('#attendanceTableBody tr');
    rows.forEach(row => {
        const buttons = row.querySelectorAll('.status-toggle-btn');
        buttons.forEach(btn => {
            btn.classList.remove('active');
            if (btn.classList.contains(status)) {
                btn.classList.add('active');
            }
        });
        
        // بروزرسانی ستون وضعیت فعلی
        const statusCell = row.querySelector('.status-pill');
        if (statusCell) {
            const statusText = status === 'present' ? 'حاضر' : (status === 'absent' ? 'غایب' : (status === 'late' ? 'تأخیر' : 'موجه'));
            const statusIcon = status === 'present' ? 'fa-check-circle' : (status === 'absent' ? 'fa-times-circle' : (status === 'late' ? 'fa-clock' : 'fa-shield-alt'));
            statusCell.className = `status-pill ${status}`;
            statusCell.innerHTML = `<i class="fas ${statusIcon}"></i> ${statusText}`;
        }
    });
    
    updateTempStats();
    showToast(`همه دانش‌آموزان به وضعیت ${status === 'present' ? 'حاضر' : (status === 'absent' ? 'غایب' : (status === 'late' ? 'تأخیر' : 'موجه'))} تغییر یافتند`, 'info');
}

function updateTempStats() {
    const classId = document.getElementById('attendanceClass')?.value;
    if (!classId || !currentAttendanceData.length) return;
    
    const date = selectedDate || new Date().toISOString().split('T')[0];
    const period = currentPeriod;
    const tempKey = `${date}_${period}_${classId}`;
    const tempStatuses = tempAttendanceStatus[tempKey] || {};
    
    let present = 0, absent = 0, late = 0, excused = 0;
    
    currentAttendanceData.forEach(student => {
        const status = tempStatuses[student.id] || student.status;
        if (status === 'present') present++;
        else if (status === 'absent') absent++;
        else if (status === 'late') late++;
        else if (status === 'excused') excused++;
    });
    
    const total = present + absent + late + excused;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;
    
    document.getElementById('statPresent').textContent = toPersianNumber(present);
    document.getElementById('statAbsent').textContent = toPersianNumber(absent);
    document.getElementById('statLate').textContent = toPersianNumber(late);
    document.getElementById('statExcused').textContent = toPersianNumber(excused);
    document.getElementById('statRate').textContent = `${rate}%`;
}

async function saveAllAttendance() {
    const classId = document.getElementById('attendanceClass')?.value;
    if (!classId) {
        showToast('لطفاً کلاس را انتخاب کنید', 'warning');
        return;
    }
    
    const date = selectedDate || new Date().toISOString().split('T')[0];
    const period = currentPeriod;
    const tempKey = `${date}_${period}_${classId}`;
    const tempStatuses = tempAttendanceStatus[tempKey] || {};
    
    const records = [];
    for (const student of currentAttendanceData) {
        const newStatus = tempStatuses[student.id];
        if (newStatus && newStatus !== student.status) {
            const note = document.getElementById(`note_${student.id}_${period}`)?.value || '';
            records.push({
                student_id: student.id,
                status: newStatus,
                note: note
            });
        }
    }
    
    if (records.length === 0) {
        showToast('هیچ تغییری برای ذخیره وجود ندارد', 'info');
        return;
    }
    
    showLoading(true);
    let successCount = 0;
    
    for (const record of records) {
        try {
            await fetchAPI('/admin/attendance', {
                method: 'POST',
                body: JSON.stringify({
                    student_id: record.student_id,
                    class_id: classId,
                    date: date,
                    period: period,
                    status: record.status,
                    note: record.note
                })
            });
            successCount++;
        } catch (err) {
            console.error('Error saving attendance:', err);
        }
    }
    
    // پاک کردن کش موقت برای این زنگ
    delete tempAttendanceStatus[tempKey];
    
    showToast(`${successCount} وضعیت حضور با موفقیت ثبت شد`, 'success');
    await loadAttendanceTable();
    showLoading(false);
}

function filterByStatus(status) {
    const rows = document.querySelectorAll('#attendanceTableBody tr');
    rows.forEach(row => {
        const statusPill = row.querySelector('.status-pill');
        if (statusPill && statusPill.classList.contains(status)) {
            row.style.display = '';
        } else {
            row.style.display = 'none';
        }
    });
}

function resetStats() {
    document.getElementById('statPresent').textContent = '0';
    document.getElementById('statAbsent').textContent = '0';
    document.getElementById('statLate').textContent = '0';
    document.getElementById('statExcused').textContent = '0';
    document.getElementById('statRate').textContent = '0%';
}

