let activeFinanceSmartSelect = null;

function financeSelectIcon(select) {
    const map = {
        paymentTypeFilter: 'fa-tag',
        paymentStatusFilter: 'fa-flag-checkered',
        paymentStudentId: 'fa-user-graduate',
        paymentType: 'fa-money-bill-transfer',
        paymentStatus: 'fa-circle-check',
        editPaymentType: 'fa-money-bill-transfer',
        editPaymentStatus: 'fa-circle-check'
    };
    return map[select.id] || 'fa-list-ul';
}

function closeFinanceSmartSelect() {
    if (activeFinanceSmartSelect?.menu) activeFinanceSmartSelect.menu.remove();
    if (activeFinanceSmartSelect?.trigger) activeFinanceSmartSelect.trigger.setAttribute('aria-expanded', 'false');
    activeFinanceSmartSelect = null;
}

function openFinanceSmartSelect(select, trigger) {
    closeFinanceSmartSelect();
    const menu = document.createElement('div');
    menu.className = 'finance-smart-menu';
    menu.setAttribute('role', 'listbox');
    Array.from(select.options).forEach(option => {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = `finance-smart-option${option.selected ? ' selected' : ''}`;
        item.disabled = option.disabled;
        item.innerHTML = `<span>${escapeHtml(option.textContent || '')}</span>${option.selected ? '<i class="fas fa-check"></i>' : ''}`;
        item.addEventListener('click', () => {
            select.value = option.value;
            select.dispatchEvent(new Event('change', { bubbles: true }));
            select._financeRefresh?.();
            closeFinanceSmartSelect();
            trigger.focus();
        });
        menu.appendChild(item);
    });
    document.body.appendChild(menu);
    const rect = trigger.getBoundingClientRect();
    const margin = 10;
    const width = Math.max(rect.width, 230);
    menu.style.width = `${width}px`;
    let left = rect.right - width;
    left = Math.max(margin, Math.min(left, window.innerWidth - width - margin));
    const menuHeight = Math.min(menu.scrollHeight, 330);
    let top = rect.bottom + 8;
    if (top + menuHeight > window.innerHeight - margin) top = Math.max(margin, rect.top - menuHeight - 8);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    trigger.setAttribute('aria-expanded', 'true');
    activeFinanceSmartSelect = { select, trigger, menu };
}

function upgradeFinanceSelects() {
    const ids = ['paymentTypeFilter','paymentStatusFilter','paymentStudentId','paymentType','paymentStatus','editPaymentType','editPaymentStatus'];
    ids.forEach(id => {
        const select = document.getElementById(id);
        if (!select || select.dataset.financeSelectReady === 'true') return;
        select.dataset.financeSelectReady = 'true';
        select.classList.add('finance-native-select');
        const host = document.createElement('div');
        host.className = 'finance-smart-host';
        select.parentNode.insertBefore(host, select);
        host.appendChild(select);
        const trigger = document.createElement('button');
        trigger.type = 'button';
        trigger.className = 'finance-smart-trigger';
        trigger.setAttribute('aria-haspopup', 'listbox');
        trigger.setAttribute('aria-expanded', 'false');
        host.appendChild(trigger);
        const refresh = () => {
            const selected = select.options[select.selectedIndex];
            trigger.innerHTML = `<span class="finance-smart-leading"><i class="fas ${financeSelectIcon(select)}"></i></span><span class="finance-smart-label">${escapeHtml(selected?.textContent || 'انتخاب کنید')}</span><i class="fas fa-chevron-down finance-smart-chevron"></i>`;
        };
        select._financeRefresh = refresh;
        select.addEventListener('change', refresh);
        trigger.addEventListener('click', event => {
            event.stopPropagation();
            if (activeFinanceSmartSelect?.select === select) closeFinanceSmartSelect();
            else openFinanceSmartSelect(select, trigger);
        });
        refresh();
    });
}

function refreshFinanceSelects() {
    ['paymentTypeFilter','paymentStatusFilter','paymentStudentId','paymentType','paymentStatus','editPaymentType','editPaymentStatus']
        .forEach(id => document.getElementById(id)?._financeRefresh?.());
}

