async function changeAdminPassword() {
    const currentPassword = document.getElementById('currentPassword')?.value || '';
    const newPassword = document.getElementById('newPassword')?.value || '';
    const confirmPassword = document.getElementById('confirmPassword')?.value || '';
    
    if (!currentPassword || !newPassword || !confirmPassword) {
        showStatusMessage('securityStatus', 'لطفاً تمام فیلدهای رمز عبور را پر کنید', 'error');
        return;
    }
    
    if (newPassword !== confirmPassword) {
        showStatusMessage('securityStatus', 'رمز عبور جدید و تکرار آن مطابقت ندارند', 'error');
        return;
    }
    
    if (newPassword.length < 6) {
        showStatusMessage('securityStatus', 'رمز عبور جدید باید حداقل ۶ کاراکتر باشد', 'error');
        return;
    }
    
    showLoading(true);
    try {
        const response = await fetchAPI('/auth/change-password', {
            method: 'POST',
            body: JSON.stringify({
                current_password: currentPassword,
                new_password: newPassword
            })
        });
        console.log('Password change response:', response);
        showStatusMessage('securityStatus', 'رمز عبور با موفقیت تغییر کرد', 'success');
        document.getElementById('currentPassword').value = '';
        document.getElementById('newPassword').value = '';
        document.getElementById('confirmPassword').value = '';
    } catch (error) {
        console.error('Password change error:', error);
        showStatusMessage('securityStatus', error.message || 'خطا در تغییر رمز عبور', 'error');
    } finally {
        showLoading(false);
    }
}

