function applyColors(colors) {
    if (colors.primary_color) {
        document.documentElement.style.setProperty('--primary', colors.primary_color);
        document.documentElement.style.setProperty('--primary-dark', colors.primary_color);
    }
    if (colors.secondary_color) {
        document.documentElement.style.setProperty('--secondary', colors.secondary_color);
    }
    if (colors.text_color) {
        document.documentElement.style.setProperty('--text-color', colors.text_color);
    }
    console.log('Colors applied:', colors);
}

async function uploadLogo() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        
        // بررسی حجم فایل (حداکثر 2MB)
        if (file.size > 2 * 1024 * 1024) {
            showStatusMessage('appearanceStatus', 'حجم فایل باید کمتر از 2 مگابایت باشد', 'error');
            return;
        }
        
        // تبدیل فایل به Base64
        const reader = new FileReader();
        reader.onload = async (event) => {
            const base64Image = event.target.result;
            
            showLoading(true);
            try {
                const response = await fetch('/api/v1/admin/upload-logo', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${localStorage.getItem('token')}`
                    },
                    body: JSON.stringify({ image: base64Image })
                });
                const result = await response.json();
                console.log('Upload logo response:', result);
                
                if (result.success) {
                    const logoPreview = document.getElementById('logoPreview');
                    if (logoPreview) {
                        logoPreview.src = result.url + '?t=' + Date.now();
                    }
                    settingsData = { ...(settingsData || {}), logo_url: result.url };
                    renderAdminSidebarBrand(settingsData);
                    showStatusMessage('appearanceStatus', 'لوگو با موفقیت آپلود شد', 'success');
                    
                    // بروزرسانی لوگو در هدر
                    const headerLogo = document.querySelector('.logo img');
                    if (headerLogo) headerLogo.src = result.url;
                } else {
                    showStatusMessage('appearanceStatus', result.error || 'خطا در آپلود لوگو', 'error');
                }
            } catch (error) {
                console.error('Upload error:', error);
                showStatusMessage('appearanceStatus', 'خطا در آپلود لوگو', 'error');
            } finally {
                showLoading(false);
            }
        };
        reader.readAsDataURL(file);
    };
    input.click();
}

