async function loadBackupList() {
    try {
        const response = await fetchAPI('/admin/backups');
        const backups = response.backups || [];
        const stats = response.stats || {};
        
        document.getElementById('backupCount').textContent = toPersianNumber(stats.total || 0);
        document.getElementById('backupSize').textContent = stats.size || '0 KB';
        document.getElementById('lastBackup').textContent = stats.lastBackup || 'ندارد';
        
        const tbody = document.getElementById('backupTableBody');
        if (!tbody) return;
        
        if (backups.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" class="empty-state">پشتیبان‌ای وجود ندارد</div></tr>';
        } else {
            tbody.innerHTML = backups.map(b => `
                <tr>
                    <td>${b.filename}</div>
                    <td>${formatDate(b.created_at)}</div>
                    <td>${formatFileSize(b.size)}</div>
                    <td><span class="badge badge-${b.type === 'auto' ? 'info' : 'secondary'}">${b.type === 'auto' ? 'خودکار' : 'دستی'}</span></div>
                    <td>
                        <div class="action-buttons">
                            <button class="action-btn" onclick="downloadBackup(${b.id})" title="دانلود"><i class="fas fa-download"></i></button>
                            <button class="action-btn danger" onclick="deleteBackup(${b.id})" title="حذف"><i class="fas fa-trash"></i></button>
                        </div>
                    </div>
                </tr>
            `).join('');
        }
    } catch (error) {
        console.error('Error loading backups:', error);
    }
}

