async function loadBackup() {
    showLoading(true);
    try {
        const response = await fetchAPI('/admin/backups');
        const backups = response.backups || [];
        const stats = response.stats || {};
        
        const html = `<div class="card slide-up"><div class="card-header"><div class="card-title"><i class="fas fa-database"></i> پشتیبان‌گیری</div><button class="btn btn-primary btn-sm" onclick="createManualBackup()"><i class="fas fa-plus"></i> پشتیبان جدید</button></div>
        <div class="card-body"><div class="stats-grid" style="grid-template-columns:repeat(3,1fr);margin-bottom:24px"><div class="stat-card"><div class="stat-value">${stats.total || 0}</div><div class="stat-label">تعداد پشتیبان‌ها</div></div>
        <div class="stat-card"><div class="stat-value">${stats.size || '۰'}</div><div class="stat-label">حجم کل</div></div>
        <div class="stat-card"><div class="stat-value">${stats.lastBackup || '-'}</div><div class="stat-label">آخرین پشتیبان</div></div></div>
        <div class="table-container"><table class="data-table"><thead><tr><th>ردیف</th><th>نام فایل</th><th>تاریخ</th><th>حجم</th><th>نوع</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody id="backupsTableBody"></tbody></table></div></div></div>`;
        
        document.getElementById('contentArea').innerHTML = html;
        
        const tbody = document.getElementById('backupsTableBody');
        if (backups.length === 0) { tbody.innerHTML = '<tr><td colspan="7" class="empty-state">پشتیبان‌ای وجود ندارد</div>'; }
        else {
            tbody.innerHTML = backups.map((b, index) => `<tr>
                <td>${index + 1}</td><td><i class="fas fa-file-archive"></i> ${b.filename}</td><td>${formatDate(b.created_at)}</td>
                <td>${formatFileSize(b.size)}</td><td><span class="badge badge-${b.type === 'auto' ? 'info' : 'secondary'}">${b.type === 'auto' ? 'خودکار' : 'دستی'}</span></td>
                <td><span class="badge badge-${b.status === 'success' ? 'success' : 'danger'}">${b.status === 'success' ? 'موفق' : 'ناموفق'}</span></td>
                <td><div class="btn-group"><button class="btn-icon-sm" onclick="downloadBackup(${b.id})"><i class="fas fa-download"></i></button><button class="btn-icon-sm danger" onclick="deleteBackup(${b.id})"><i class="fas fa-trash"></i></button></div></td>
            <tr>`).join('');
        }
    } catch (error) { showToast('خطا در بارگذاری پشتیبان‌ها', error); }
    showLoading(false);
}

function formatFileSize(bytes) { if (!bytes) return '0 B'; const k = 1024; const sizes = ['B', 'KB', 'MB', 'GB']; const i = Math.floor(Math.log(bytes) / Math.log(k)); return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]; }
async function createManualBackup() { showLoading(true); try { await fetchAPI('/admin/backups', { method: 'POST', body: JSON.stringify({ type: 'manual' }) }); showToast('پشتیبان‌گیری با موفقیت انجام شد', 'success'); await loadBackup(); } catch (error) { showToast(error.message || 'خطا در ایجاد پشتیبان', 'error'); } finally { showLoading(false); } }
function downloadBackup(id) { if (!id) return showToast('شناسه فایل پشتیبان معتبر نیست', 'error'); window.open(`/api/v1/admin/backups/${id}/download`, '_blank', 'noopener'); showToast('دانلود پشتیبان آغاز شد', 'success'); }
async function deleteBackup(id) { if (!confirm('آیا از حذف این پشتیبان مطمئن هستید؟')) return; showLoading(true); try { await fetchAPI(`/admin/backups/${id}`, { method: 'DELETE' }); showToast('پشتیبان حذف شد', 'success'); await loadBackup(); } catch (error) { showToast(error.message || 'خطا در حذف پشتیبان', 'error'); } finally { showLoading(false); } }

