function ensureAdminHomepageNav() {
    const menu = document.getElementById('navMenu');
    if (!menu) return;
    const requiredTabs = ['home-news', 'gallery-manager', 'honors', 'services-page', 'about-page', 'timeline-page', 'faq-page', 'contact-page'];
    if (requiredTabs.every(tab => menu.querySelector(`.nav-item[data-tab="${tab}"]`))) return;
    const anchor =
        menu.querySelector('.nav-item[data-tab="about-page"]') ||
        menu.querySelector('.nav-item[data-tab="services-page"]') ||
        menu.querySelector('.nav-item[data-tab="honors"]') ||
        menu.querySelector('.nav-item[data-tab="announcements"]') ||
        menu.querySelector('.nav-item[data-tab="polls"]');
    if (!anchor) return;
    const links = document.createElement('div');
    links.innerHTML = `
        ${menu.querySelector('.nav-item[data-tab="home-news"]') ? '' : '<a class="nav-item" data-tab="home-news" href="/dashboard/admin/home-news"><i class="fas fa-newspaper"></i><span>اخبار صفحه اصلی</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="gallery-manager"]') ? '' : '<a class="nav-item" data-tab="gallery-manager" href="/dashboard/admin/gallery-manager"><i class="fas fa-images"></i><span>مدیریت گالری</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="honors"]') ? '' : '<a class="nav-item" data-tab="honors" href="/dashboard/admin/honors"><i class="fas fa-trophy"></i><span>مدیریت افتخارآفرینان</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="services-page"]') ? '' : '<a class="nav-item" data-tab="services-page" href="/dashboard/admin/services-page"><i class="fas fa-chalkboard-teacher"></i><span>مدیریت صفحه خدمات</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="about-page"]') ? '' : '<a class="nav-item" data-tab="about-page" href="/dashboard/admin/about-page"><i class="fas fa-school"></i><span>مدیریت صفحه درباره ما</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="timeline-page"]') ? '' : '<a class="nav-item" data-tab="timeline-page" href="/dashboard/admin/timeline-page"><i class="fas fa-timeline"></i><span>مدیریت تاریخچه مدرسه</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="faq-page"]') ? '' : '<a class="nav-item" data-tab="faq-page" href="/dashboard/admin/faq-page"><i class="fas fa-circle-question"></i><span>مدیریت سوالات متداول</span></a>'}
        ${menu.querySelector('.nav-item[data-tab="contact-page"]') ? '' : '<a class="nav-item" data-tab="contact-page" href="/dashboard/admin/contact-page"><i class="fas fa-headset"></i><span>مدیریت صفحه ارتباط با ما</span></a>'}
    `;
    Array.from(links.children).reverse().forEach(node => anchor.insertAdjacentElement('afterend', node));
}

function homepageAdminEscape(value) {
    return String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
}

function homepageAdminNumber(value) {
    return toPersianNumber(value ?? 0);
}

function homepageAdminDate(value) {
    if (!value) return 'بدون تاریخ';
    try {
        const date = new Date(value);
        if (Number.isNaN(date.getTime())) return homepageAdminEscape(value);
        return new Intl.DateTimeFormat('fa-IR', { year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
    } catch (error) {
        return homepageAdminEscape(value);
    }
}

function homepageAdminReadImage(file, maxSizeMB = 5) {
    return new Promise((resolve, reject) => {
        if (!file) return resolve(null);
        if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) return reject(new Error('فقط JPG، PNG و WEBP مجاز است'));
        if (file.size > maxSizeMB * 1024 * 1024) return reject(new Error(`حجم تصویر نباید بیشتر از ${homepageAdminNumber(maxSizeMB)} مگابایت باشد`));
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error('خواندن تصویر انجام نشد'));
        reader.readAsDataURL(file);
    });
}

