async function loadHomepageNewsAdmin() {
    showLoading(true);
    try {
        const response = await fetchAPI('/admin/homepage-news');
        homeNewsAdminState.items = Array.isArray(response.news) ? response.news : [];
        homeNewsAdminState.editingId = null;
        homeNewsAdminState.imageData = null;
        renderHomepageNewsAdmin();
    } catch (error) {
        document.getElementById('contentArea').innerHTML = `<div class="empty-state"><i class="fas fa-triangle-exclamation fa-3x" style="color:#ef4444;margin-bottom:1rem"></i><h4>خطا در بارگذاری اخبار صفحه اصلی</h4><p>${homepageAdminEscape(error.message)}</p></div>`;
    } finally {
        showLoading(false);
    }
}


