async function loadStudentHonorsAdmin() {
    showLoading(true);
    try {
        const [honorsResponse, studentsResponse] = await Promise.all([
            fetchAPI('/admin/honors'),
            fetchAPI('/admin/honors/students').catch(() => ({ success: true, students: [] }))
        ]);
        honorsAdminState.items = Array.isArray(honorsResponse.honors) ? honorsResponse.honors : [];
        honorsAdminState.students = Array.isArray(studentsResponse.students) ? studentsResponse.students : [];
        renderStudentHonorsAdmin();
    } catch (error) {
        document.getElementById('contentArea').innerHTML = `<div class="empty-state"><i class="fas fa-triangle-exclamation fa-3x" style="color:#ef4444;margin-bottom:1rem"></i><h4>خطا در بارگذاری افتخارآفرینان</h4><p>${homepageAdminEscape(error.message)}</p></div>`;
    } finally { showLoading(false); }
}

function renderStudentHonorsAdmin() {
    const area = document.getElementById('contentArea'); if (!area) return;
    const total = honorsAdminState.items.length;
    const active = honorsAdminState.items.filter(item => Number(item.is_active) === 1).length;
    const featured = honorsAdminState.items.filter(item => Number(item.is_featured) === 1).length;
    const categoriesWithData = HONOR_CATEGORY_KEYS.filter(key => honorsAdminState.items.some(item => item.category === key)).length;
    area.innerHTML = `
        ${honorsStyles()}
        <div class="honors-page">
            <div class="honors-stats">
                <div class="honor-stat"><span class="honor-stat-icon"><i class="fas fa-trophy"></i></span><strong>${honorStatNumber(total)}</strong><b>کل افتخارها</b><small>رکوردهای ثبت‌شده</small></div>
                <div class="honor-stat"><span class="honor-stat-icon"><i class="fas fa-circle-check"></i></span><strong>${honorStatNumber(active)}</strong><b>فعال</b><small>قابل نمایش و استفاده</small></div>
                <div class="honor-stat"><span class="honor-stat-icon"><i class="fas fa-star"></i></span><strong>${honorStatNumber(featured)}</strong><b>ویژه</b><small>افتخارهای شاخص</small></div>
                <div class="honor-stat"><span class="honor-stat-icon"><i class="fas fa-layer-group"></i></span><strong>${honorStatNumber(categoriesWithData)}</strong><b>دسته فعال</b><small>از ${honorStatNumber(HONOR_CATEGORY_KEYS.length)} دسته</small></div>
            </div>
            <section class="honors-panel">
                <header class="honors-head"><div class="honors-title"><span><i class="fas fa-trophy"></i></span><div><h3>مدیریت افتخارآفرینان</h3><p>دانش‌آموزان افتخارآفرین را بر اساس نوع موفقیت ثبت و مدیریت کنید.</p></div></div><div class="honors-tools"><div class="honors-search"><i class="fas fa-search"></i><input id="honorsSearch" placeholder="جستجوی دانش‌آموز، عنوان یا توضیح..." oninput="renderStudentHonorsList(this.value)"></div><button class="btn btn-primary" onclick="openStudentHonorModal()"><i class="fas fa-plus"></i> ثبت افتخار جدید</button><button class="btn btn-danger-soft" onclick="deleteAllStudentHonors()"><i class="fas fa-trash-can"></i> حذف همه</button><button class="btn btn-soft" onclick="loadStudentHonorsAdmin()"><i class="fas fa-sync"></i> تازه‌سازی</button></div></header>
                <div class="honors-cats">
                    <button class="honor-cat ${honorsAdminState.selectedCategory === 'all' ? 'active' : ''}" onclick="selectHonorCategory('all')"><i class="fas fa-border-all"></i><span>همه دسته‌ها</span><small>${honorStatNumber(total)} مورد</small></button>
                    ${HONOR_CATEGORY_KEYS.map(key => { const meta = honorCategoryMeta(key); const count = honorsAdminState.items.filter(item => item.category === key).length; return `<button class="honor-cat ${honorsAdminState.selectedCategory === key ? 'active' : ''}" onclick="selectHonorCategory('${key}')"><i class="fas ${meta.icon}"></i><span>${meta.short}</span><small>${honorStatNumber(count)} مورد</small></button>`; }).join('')}
                </div>
                <div class="honors-grid" id="honorsList"></div>
            </section>
        </div>`;
    renderStudentHonorsList();
}

function selectHonorCategory(category) { honorsAdminState.selectedCategory = category || 'all'; renderStudentHonorsAdmin(); }

function filteredHonors(search = '') {
    const term = String(search || '').trim().toLowerCase();
    return honorsAdminState.items.filter(item => {
        const categoryOk = honorsAdminState.selectedCategory === 'all' || item.category === honorsAdminState.selectedCategory;
        if (!categoryOk) return false;
        if (!term) return true;
        return [item.student_name, item.achievement_title, item.rank_title, item.achievement_level, item.description, honorCategoryName(item.category), item.class_name]
            .some(value => String(value || '').toLowerCase().includes(term));
    });
}

function renderStudentHonorsList(search = '') {
    const list = document.getElementById('honorsList'); if (!list) return;
    const items = filteredHonors(search);
    if (!items.length) {
        const selectedText = honorsAdminState.selectedCategory === 'all' ? 'این بخش' : honorCategoryName(honorsAdminState.selectedCategory);
        list.innerHTML = `<div class="honor-empty"><i class="fas fa-trophy"></i><h4>برای ${homepageAdminEscape(selectedText)} افتخاری ثبت نشده است</h4><p>اطلاعات این صفحه از بخش افتخارآفرینان صفحه اصلی خوانده می‌شود؛ برای اضافه‌کردن مورد جدید روی ثبت افتخار جدید بزنید.</p></div>`;
        return;
    }
    list.innerHTML = items.map(item => {
        const meta = honorCategoryMeta(item.category);
        const initial = homepageAdminEscape((item.student_name || 'د').trim().slice(0, 1));
        const avatar = item.avatar_url ? `<img src="${homepageAdminEscape(item.avatar_url)}" alt="${homepageAdminEscape(item.student_name)}">` : `<span>${initial}</span>`;
        return `<article class="honor-card honoree-admin-card">
            <div class="honor-card-visual">
                <div class="honor-avatar">${avatar}</div>
                ${Number(item.is_featured) === 1 ? '<span class="honor-feature-ribbon"><i class="fas fa-star"></i> ویژه</span>' : ''}
            </div>
            <div class="honor-card-body">
                <div class="honor-card-title-row">
                    <div>
                        <h4>${homepageAdminEscape(item.student_name)}</h4>
                        <p class="honor-card-subtitle">${homepageAdminEscape(item.achievement_title)}</p>
                    </div>
                    <span class="honor-cat-badge"><i class="fas ${meta.icon}"></i>${meta.short}</span>
                </div>
                <div class="honor-homepage-details">
                    <p><i class="fas fa-link"></i><span>${homepageAdminEscape(honorPageLabel(inferHonorPageKeyForAdmin(item)))}</span></p>
                    ${item.class_name ? `<p><i class="fas fa-school"></i><span>${homepageAdminEscape(item.class_name)}</span></p>` : ''}
                    ${item.achievement_level ? `<p><i class="fas fa-layer-group"></i><span>${homepageAdminEscape(item.achievement_level)}</span></p>` : ''}
                    ${item.rank_title ? `<p><i class="fas fa-award"></i><span>${homepageAdminEscape(item.rank_title)}</span></p>` : ''}
                    ${item.description ? `<p><i class="fas fa-circle-info"></i><span>${homepageAdminEscape(item.description)}</span></p>` : ''}
                </div>
                <div class="honor-meta">
                    ${item.award_date ? `<span class="honor-pill"><i class="far fa-calendar"></i>${honorDate(item.award_date)}</span>` : ''}
                    <span class="honor-pill ${Number(item.is_active) === 1 ? 'on' : 'off'}">${Number(item.is_active) === 1 ? 'فعال' : 'غیرفعال'}</span>
                </div>
                <div class="honor-actions">
                    <button class="btn btn-soft" onclick="openStudentHonorModal(${Number(item.id)})"><i class="fas fa-pen"></i> ویرایش</button>
                    <button class="btn btn-danger-soft" onclick="deleteStudentHonor(${Number(item.id)})"><i class="fas fa-trash"></i> حذف</button>
                </div>
            </div>
        </article>`;
    }).join('');
}

function studentHonorOptions(selectedId = '') {
    const selected = Number(selectedId || 0);
    return `<option value="">انتخاب از دانش‌آموزان ثبت‌شده</option>${honorsAdminState.students.map(student => `<option value="${Number(student.id)}" ${Number(student.id) === selected ? 'selected' : ''}>${homepageAdminEscape(honorStudentLabel(student))}</option>`).join('')}`;
}

function honorDetailsFromItem(item = {}) {
    const raw = item.details_json || item.details || '{}';
    if (raw && typeof raw === 'object') return raw;
    try { return JSON.parse(String(raw || '{}')); } catch { return {}; }
}

function honorFieldValue(details, key, fallback = '') {
    const value = details && Object.prototype.hasOwnProperty.call(details, key) ? details[key] : fallback;
    return homepageAdminEscape(Array.isArray(value) ? value.join(', ') : (value ?? ''));
}

function honorStudentSearchOptions() {
    return honorsAdminState.students.map(student => {
        const label = honorStudentLabel(student);
        return `<option value="${homepageAdminEscape(label)}" data-id="${Number(student.id)}"></option>`;
    }).join('');
}

function normalizeHonorTypedName(value = '') {
    return String(value || '').replace(/\s+/g, ' ').trim();
}

function honorSelectedClassName() {
    return document.getElementById('honorStudentClassName')?.value || '';
}

function honorSetSelectedClassName(className = '') {
    const value = String(className || '').replace(/^کلاس\s*[:：]?\s*/i, '').trim();
    const input = document.getElementById('honorStudentClassName');
    const display = document.getElementById('honorStudentClassDisplay');
    if (input) input.value = value;
    if (display) display.value = value;
}

function honorStudentIdentityLabel(student) {
    if (!student) return '';
    const parts = [];
    if (student.class_name) parts.push(`کلاس: ${student.class_name}`);
    if (student.username) parts.push(`کد/نام کاربری: ${student.username}`);
    if (student.phone) parts.push(`تلفن: ${student.phone}`);
    return parts.join(' | ') || `شناسه دانش‌آموز: ${student.id}`;
}

function findHonorStudentsByTypedName(name = '') {
    const typed = normalizeHonorTypedName(name);
    if (!typed) return [];
    return honorsAdminState.students.filter(student => normalizeHonorTypedName(student.name) === typed);
}

function findHonorStudentByTypedName(name = '') {
    const matches = findHonorStudentsByTypedName(name);
    return matches.length === 1 ? matches[0] : null;
}

function honorStudentMatchesBySearch(term = '') {
    const typed = normalizeHonorTypedName(term).toLowerCase();
    if (!typed) return [];
    const normalize = value => normalizeHonorTypedName(value).toLowerCase();
    return honorsAdminState.students
        .filter(student => normalize(student.name).includes(typed))
        .slice(0, 30);
}

function ensureHonorStudentFloatingList() {
    let list = document.getElementById('honorStudentFloatingList');
    if (!list) {
        list = document.createElement('div');
        list.id = 'honorStudentFloatingList';
        list.className = 'honor-student-floating-list';
        list.style.display = 'none';
        document.body.appendChild(list);
    }
    return list;
}


function bindHonorStudentFloatingListEvents() {
    const list = ensureHonorStudentFloatingList();
    if (!list || list.dataset.bound === '1') return;
    list.dataset.bound = '1';
    const handler = event => {
        const item = event.target.closest('.honor-student-floating-item');
        if (!item) return;
        event.preventDefault();
        event.stopPropagation();
        selectHonorStudentSuggestion(item.dataset.studentId, item.dataset.className || '');
    };
    list.addEventListener('mousedown', handler);
    list.addEventListener('click', handler);
}

function hideHonorStudentFloatingList() {
    const list = document.getElementById('honorStudentFloatingList');
    if (list) {
        list.style.display = 'none';
        list.innerHTML = '';
    }
}

function positionHonorStudentFloatingList() {
    const input = document.getElementById('honorStudentName');
    const list = document.getElementById('honorStudentFloatingList');
    if (!input || !list || list.style.display === 'none') return;
    const rect = input.getBoundingClientRect();
    list.style.width = `${rect.width}px`;
    list.style.left = `${rect.left}px`;
    list.style.top = `${rect.bottom + 8}px`;
}

function renderHonorStudentAutocomplete(matches = [], typedName = '', forceHide = false) {
    const typed = normalizeHonorTypedName(typedName);
    const list = ensureHonorStudentFloatingList();
    bindHonorStudentFloatingListEvents();
    if (forceHide || !typed) {
        hideHonorStudentFloatingList();
        return;
    }
    if (!matches.length) {
        list.innerHTML = `<div class="honor-student-floating-empty"><i class="fas fa-search"></i> دانش‌آموزی با این عبارت پیدا نشد</div>`;
    } else {
        list.innerHTML = matches.map(student => {
            const classBadge = student.class_name ? `کلاس: ${student.class_name}` : 'کلاس نامشخص';
            const detailParts = [];
            if (student.username) detailParts.push(`کد/نام کاربری: ${student.username}`);
            if (student.phone) detailParts.push(`تلفن: ${student.phone}`);
            const detail = detailParts.join(' | ');
            return `<button type="button" class="honor-student-floating-item" data-student-id="${Number(student.id)}" data-class-name="${homepageAdminEscape(String(student.class_name || ''))}">
                <span><b>${homepageAdminEscape(student.name || 'دانش‌آموز')}</b>${detail ? `<small>${homepageAdminEscape(detail)}</small>` : ''}</span>
                <em class="honor-student-floating-class">${homepageAdminEscape(classBadge)}</em>
            </button>`;
        }).join('');
    }
    list.style.display = 'block';
    positionHonorStudentFloatingList();
}

function renderHonorStudentDisambiguation(matches = [], selectedId = '') {
    const box = document.getElementById('honorStudentDisambiguation');
    if (!box) return;
    box.innerHTML = '';
    box.style.display = 'none';
}


function selectHonorDuplicateStudent(id, className = '') {
    selectHonorStudentSuggestion(id, className);
}

function selectHonorStudentSuggestion(id, className = '') {
    const numericId = Number(id || 0);
    const normalizedClass = String(className || '').trim();
    const student = honorsAdminState.students.find(item => Number(item.id) === numericId && String(item.class_name || '').trim() === normalizedClass)
        || honorsAdminState.students.find(item => Number(item.id) === numericId);
    if (!student) return;
    const finalClass = normalizedClass || String(student.class_name || '').trim();
    const hidden = document.getElementById('honorStudentId');
    const input = document.getElementById('honorStudentName');
    if (hidden) hidden.value = Number(student.id);
    honorSetSelectedClassName(finalClass);
    if (input) input.value = student.name || '';
    hideHonorStudentFloatingList();
    renderHonorStudentDisambiguation(findHonorStudentsByTypedName(student.name), student.id);
}

function bindHonorStudentSearchInput() {
    const input = document.getElementById('honorStudentName');
    if (!input || input.dataset.honorSearchBound === '1') return;
    input.dataset.honorSearchBound = '1';
    const show = () => honorStudentSearchChanged(false);
    input.addEventListener('input', show);
    input.addEventListener('focus', show);
    input.addEventListener('keyup', show);
    input.addEventListener('change', show);
    window.addEventListener('resize', positionHonorStudentFloatingList);
    window.addEventListener('scroll', positionHonorStudentFloatingList, true);
    document.addEventListener('mousedown', event => {
        const list = document.getElementById('honorStudentFloatingList');
        if (!list || list.style.display === 'none') return;
        if (event.target === input || list.contains(event.target)) return;
        hideHonorStudentFloatingList();
    });
}

function honorStudentSearchChanged(forceHideAutocomplete = false) {
    const nameInput = document.getElementById('honorStudentName');
    const hidden = document.getElementById('honorStudentId');
    const typedName = normalizeHonorTypedName(nameInput?.value || '');
    const currentId = hidden?.value || '';
    const currentClass = honorSelectedClassName();
    const exactMatches = findHonorStudentsByTypedName(typedName);
    const searchMatches = honorStudentMatchesBySearch(typedName);

    const stillSelected = exactMatches.some(student =>
        String(student.id) === String(currentId) &&
        String(student.class_name || '').trim() === String(currentClass || '').trim()
    );
    if (!stillSelected) {
        if (hidden) hidden.value = '';
        honorSetSelectedClassName('');
        renderHonorStudentDisambiguation([]);
    }

    renderHonorStudentAutocomplete(searchMatches, typedName, forceHideAutocomplete);
}

function validateHonorStudentTypedName() {
    const nameInput = document.getElementById('honorStudentName');
    const hidden = document.getElementById('honorStudentId');
    const typedName = normalizeHonorTypedName(nameInput?.value || '');
    if (nameInput) nameInput.value = typedName;
    if (!typedName) {
        if (hidden) hidden.value = '';
        honorSetSelectedClassName('');
        hideHonorStudentFloatingList();
        showToast('نام و نام خانوادگی دانش‌آموز الزامی است', 'error');
        return null;
    }
    const matches = findHonorStudentsByTypedName(typedName);
    if (!matches.length) {
        if (hidden) hidden.value = '';
        honorSetSelectedClassName('');
        showToast('دانش‌آموزی با این نام و نام خانوادگی در سیستم ثبت نشده است', 'error');
        return null;
    }
    const selectedId = hidden?.value || '';
    const selectedClass = honorSelectedClassName();
    const found = selectedId
        ? matches.find(student => String(student.id) === String(selectedId) && String(student.class_name || '').trim() === String(selectedClass || '').trim())
        : null;
    if (!found) {
        renderHonorStudentAutocomplete(honorStudentMatchesBySearch(typedName), typedName, false);
        showToast('از لیست جستجو، دانش‌آموز و کلاس درست را انتخاب کنید', 'error');
        return null;
    }
    renderHonorStudentDisambiguation(matches, found.id);
    return found;
}


function honorOptionList(options, selected = '') {
    return options.map(value => `<option value="${homepageAdminEscape(value)}" ${String(value) === String(selected) ? 'selected' : ''}>${homepageAdminEscape(value)}</option>`).join('');
}

function honorSelectField(id, label, options, selected = '', required = true) {
    return `<div class="honor-field"><label>${homepageAdminEscape(label)}${required ? ' *' : ''}</label><select class="form-control honor-smart-select" id="${id}" ${required ? 'required' : ''}><option value="">انتخاب کنید</option>${honorOptionList(options, selected)}</select></div>`;
}

function honorTextField(id, label, value = '', placeholder = '', required = true, type = 'text') {
    return `<div class="honor-field"><label>${homepageAdminEscape(label)}${required ? ' *' : ''}</label><input id="${id}" type="${type}" ${type === 'number' ? 'inputmode="numeric"' : ''} ${required ? 'required' : ''} value="${homepageAdminEscape(value ?? '')}" placeholder="${homepageAdminEscape(placeholder)}"></div>`;
}

function honorTechnologyChips(selected = []) {
    const selectedList = Array.isArray(selected) ? selected.map(String) : String(selected || '').split(',').map(item => item.trim()).filter(Boolean);
    const technologies = ['Python','Arduino','C++','Scratch','LEGO Robotics','JavaScript','AI','Robotics'];
    return `<div class="honor-multiselect">${technologies.map(tech => `<label class="honor-tech-chip ${selectedList.includes(tech) ? 'active' : ''}"><input type="checkbox" name="honorTech" value="${homepageAdminEscape(tech)}" ${selectedList.includes(tech) ? 'checked' : ''} onchange="this.closest('.honor-tech-chip').classList.toggle('active', this.checked)"><span>${homepageAdminEscape(tech)}</span></label>`).join('')}</div>`;
}

function inferHonorPageKeyFromOlympiad(olympiad = '') {
    const value = String(olympiad || '').toLowerCase().trim();
    if (value.includes('sasmo')) return 'sasmo';
    if (value.includes('waterloo') || value.includes('واترلو')) return 'waterloo';
    if (value.includes('ijmo')) return 'ijmo';
    return '';
}

function syncHonorOlympiadPageKey() {
    const olympiad = String(document.getElementById('honorDynOlympiad')?.value || '').trim();
    const inferred = inferHonorPageKeyFromOlympiad(olympiad);
    const page = document.getElementById('honorPageKey');
    if (page && inferred) page.value = inferred;
}

