function honorDynValue(id) { return String(document.getElementById(id)?.value || '').trim(); }
function honorDynRequired(id, label) {
    const value = honorDynValue(id);
    if (!value) throw new Error(`${label} الزامی است`);
    return value;
}
function collectHonorDynamicDetails(category) {
    const details = { category };
    if (category === 'international_medalists') {
        details.olympiad_type = honorDynRequired('honorDynOlympiad', 'نوع المپیاد');
        details.medal_type = honorDynRequired('honorDynMedal', 'نوع مدال');
        details.rank = honorDynRequired('honorDynRank', 'رتبه در المپیاد');
        details.year = honorDynRequired('honorDynYear', 'سال مسابقه');
        details.country = honorDynValue('honorDynCountry');
        details.stage = honorDynRequired('honorDynStage', 'مرحله مسابقه');
    } else if (category === 'sampad_acceptance') {
        details.exam_type = honorDynRequired('honorDynExamType', 'نوع آزمون');
        details.grade = honorDynRequired('honorDynGrade', 'پایه تحصیلی');
        details.rank = honorDynRequired('honorDynRank', 'رتبه');
        details.year = honorDynRequired('honorDynYear', 'سال آزمون');
        details.province = honorDynRequired('honorDynProvince', 'استان یا منطقه');
    } else if (category === 'art_honors') {
        details.art_type = honorDynRequired('honorDynArtType', 'نوع هنر');
        details.event_name = honorDynRequired('honorDynEventName', 'نام مسابقه یا جشنواره');
        details.place = honorDynRequired('honorDynPlace', 'مقام کسب شده');
        details.level = honorDynRequired('honorDynLevel', 'سطح مسابقه');
        details.year = honorDynRequired('honorDynYear', 'سال مسابقه');
    } else if (category === 'programming_robotics') {
        details.competition_type = honorDynRequired('honorDynCompetitionType', 'نوع مسابقه');
        details.competition_name = honorDynRequired('honorDynCompetitionName', 'نام مسابقه');
        details.technologies = Array.from(document.querySelectorAll('input[name="honorTech"]:checked')).map(input => input.value);
        details.place = honorDynRequired('honorDynPlace', 'مقام');
        details.level = honorDynRequired('honorDynLevel', 'سطح مسابقه');
        details.year = honorDynRequired('honorDynYear', 'سال مسابقه');
    } else if (category === 'martial_arts') {
        details.sport_type = honorDynRequired('honorDynSport', 'رشته ورزشی');
        details.match_type = honorDynRequired('honorDynMatchType', 'نوع مسابقه');
        details.weight_age = honorDynRequired('honorDynWeightAge', 'وزن یا رده سنی');
        details.place = honorDynRequired('honorDynPlace', 'مقام');
        details.level = honorDynRequired('honorDynLevel', 'سطح مسابقه');
        details.year = honorDynRequired('honorDynYear', 'سال مسابقه');
    } else if (category === 'research_innovation') {
        details.activity_type = honorDynRequired('honorDynActivity', 'نوع فعالیت');
        details.project_title = honorDynRequired('honorDynProjectTitle', 'عنوان پروژه');
        details.science_field = honorDynRequired('honorDynScienceField', 'حوزه علمی');
        details.place = honorDynRequired('honorDynPlace', 'مقام');
        details.level = honorDynRequired('honorDynLevel', 'سطح مسابقه');
        details.year = honorDynRequired('honorDynYear', 'سال');
    }
    return details;
}

function buildHonorDisplayFromDetails(category, details, manualTitle = '') {
    const titleInput = String(manualTitle || '').trim();
    const output = { title: titleInput, level: '', rank: '' };
    if (category === 'international_medalists') {
        output.title = titleInput || `افتخارآفرینی در المپیاد ${details.olympiad_type}`;
        output.rank = [details.medal_type, details.rank ? `رتبه ${details.rank}` : ''].filter(Boolean).join(' - ');
        output.level = [details.country, details.stage, details.year].filter(Boolean).join(' - ');
    } else if (category === 'sampad_acceptance') {
        output.title = titleInput || `پذیرفته‌شده ${details.exam_type}`;
        output.rank = details.rank ? `رتبه ${details.rank}` : '';
        output.level = [details.grade, details.province, details.year].filter(Boolean).join(' - ');
    } else if (category === 'art_honors') {
        output.title = titleInput || `${details.art_type} - ${details.event_name}`;
        output.rank = details.place || '';
        output.level = [details.level, details.year].filter(Boolean).join(' - ');
    } else if (category === 'programming_robotics') {
        output.title = titleInput || `${details.competition_type} - ${details.competition_name}`;
        output.rank = details.place || '';
        output.level = [details.level, details.year, (details.technologies || []).join(', ')].filter(Boolean).join(' - ');
    } else if (category === 'martial_arts') {
        output.title = titleInput || `${details.sport_type} - ${details.match_type}`;
        output.rank = details.place ? `مقام ${details.place}` : '';
        output.level = [details.weight_age, details.level, details.year].filter(Boolean).join(' - ');
    } else if (category === 'research_innovation') {
        output.title = titleInput || `${details.activity_type} - ${details.project_title}`;
        output.rank = details.place || '';
        output.level = [details.science_field, details.level, details.year].filter(Boolean).join(' - ');
    }
    return output;
}

