function honorStudentSelectChanged() {
    const id = Number(document.getElementById('honorStudentId')?.value || 0);
    const student = honorsAdminState.students.find(item => Number(item.id) === id);
    if (student) document.getElementById('honorStudentName').value = student.name || '';
}
function closeStudentHonorModal() { hideHonorStudentFloatingList(); const host = document.getElementById('modalsContainer'); const modal = document.getElementById('studentHonorModal'); if (host) host.innerHTML = ''; else modal?.remove(); document.body.classList.remove('modal-open','honor-modal-open'); honorsAdminState.editingId = null; }
function studentHonorModalBackdrop(event) { if (event.target?.id === 'studentHonorModal') closeStudentHonorModal(); }
function honorDateForPayload() { const value = document.getElementById('honorDate')?.value.trim() || ''; if (!value) return null; const gregorian = jalaliToGregorian(value); if (!gregorian) throw new Error('تاریخ افتخار معتبر نیست'); return gregorian; }

async function saveStudentHonor(event) {
    event.preventDefault();
    const matchedStudent = validateHonorStudentTypedName();
    if (!matchedStudent) return;
    let awardDate = null;
    try { awardDate = honorDateForPayload(); } catch (error) { return showToast(error.message, 'error'); }
    const category = document.getElementById('honorCategory').value;
    let details = {};
    try { details = collectHonorDynamicDetails(category); } catch (error) { return showToast(error.message, 'error'); }
    const display = buildHonorDisplayFromDetails(category, details, document.getElementById('honorTitle').value.trim());
    const levelValue = document.getElementById('honorLevel').value.trim() || display.level;
    const rankValue = document.getElementById('honorRank').value.trim() || display.rank;
    if (honorSelectedClassName()) {
        details.class_name = honorSelectedClassName();
        details.grade = honorSelectedClassName();
    }
    const payload = {
        student_id: matchedStudent?.id || document.getElementById('honorStudentId').value || null,
        student_name: document.getElementById('honorStudentName').value.trim(),
        category,
        page_key: category === 'international_medalists' ? (inferHonorPageKeyFromOlympiad(details.olympiad_type || details.olympiad) || defaultHonorPageKey(category)) : defaultHonorPageKey(category),
        achievement_title: display.title,
        achievement_level: levelValue,
        rank_title: rankValue,
        award_date: awardDate,
        description: document.getElementById('honorDescription').value.trim(),
        details_json: details,
        is_active: document.getElementById('honorActive').checked,
        is_featured: document.getElementById('honorFeatured').checked
    };
    if (!payload.student_name) return showToast('نام دانش‌آموز الزامی است', 'error');
    if (!payload.category) return showToast('دسته افتخار الزامی است', 'error');
    if (!payload.achievement_title) return showToast('عنوان افتخار قابل ساخت نیست؛ اطلاعات تخصصی را کامل کن', 'error');
    showLoading(true);
    try {
        const endpoint = honorsAdminState.editingId ? `/admin/honors/${honorsAdminState.editingId}` : '/admin/honors';
        await fetchAPI(endpoint, { method: honorsAdminState.editingId ? 'PUT' : 'POST', body: JSON.stringify(payload) });
        showToast(honorsAdminState.editingId ? 'افتخار به‌روزرسانی شد' : 'افتخار جدید ثبت شد', 'success');
        closeStudentHonorModal();
        await loadStudentHonorsAdmin();
    } catch (error) { showToast(error.message || 'ذخیره افتخار انجام نشد', 'error'); }
    finally { showLoading(false); }
}

async function deleteStudentHonor(id) {
    const item = honorsAdminState.items.find(row => Number(row.id) === Number(id));
    const title = item ? ` «${item.student_name} - ${item.achievement_title}»` : '';
    if (!confirm(`رکورد افتخار${title} حذف شود؟`)) return;
    showLoading(true);
    try { await fetchAPI(`/admin/honors/${id}`, { method: 'DELETE' }); showToast('رکورد افتخار حذف شد', 'success'); closeStudentHonorModal(); await loadStudentHonorsAdmin(); }
    catch (error) { showToast(error.message || 'حذف افتخار انجام نشد', 'error'); }
    finally { showLoading(false); }
}

async function deleteAllStudentHonors() {
    const total = honorsAdminState.items.length;
    if (!total) return showToast('هیچ افتخاری برای حذف وجود ندارد', 'info');
    const firstConfirm = confirm(`همه ${homepageAdminNumber(total)} رکورد افتخارآفرینان حذف شود؟ این کار قابل برگشت نیست.`);
    if (!firstConfirm) return;
    const secondConfirm = confirm('برای اطمینان: با حذف همه، تمام کارت‌های افتخارآفرینان از این پنل پاک می‌شوند. ادامه می‌دهید؟');
    if (!secondConfirm) return;
    showLoading(true);
    try {
        await fetchAPI('/admin/honors/all', { method: 'DELETE' });
        honorsAdminState.items = [];
        showToast('همه افتخارآفرینان حذف شدند', 'success');
        closeStudentHonorModal();
        renderStudentHonorsAdmin();
    } catch (error) {
        showToast(error.message || 'حذف همه افتخارآفرینان انجام نشد', 'error');
    } finally {
        showLoading(false);
    }
}

