async function deleteContactMessageAdmin(id){
    if(!confirm('آیا از حذف این پیام مطمئن هستید؟ این عملیات قابل بازگشت نیست.'))return;
    try{
        const res=await fetchAPI(`/admin/contact-messages/${id}`,{method:'DELETE'});
        showToast(res.message||'پیام حذف شد','success');
        loadContactMessagesAdmin(contactMessagesState.page||1);
    }catch(error){showToast(error.message||'خطا در حذف پیام','error');}
}


