function selectContactReplyStatusAdmin(status,btn){
    const allowed=['in_progress','closed','spam'];
    if(!allowed.includes(status))return;
    window.currentContactReplyStatus=status;
    const box=btn?.closest?.('.cmr2-status-actions')||document.querySelector('#contactAdminModal .cmr2-status-actions');
    box?.querySelectorAll?.('[data-contact-reply-status]')?.forEach(item=>{
        const selected=item.dataset.contactReplyStatus===status;
        item.classList.toggle('is-selected',selected);
        item.setAttribute('aria-pressed',selected?'true':'false');
    });
    const pill=document.querySelector('#contactAdminModal .cmr2-status');
    if(pill){
        pill.className=`cmr2-pill cmr2-status ct-message-status ${status}`;
        pill.innerHTML=`<span class="dot"></span>${contactStatusLabelAdmin(status)}`;
    }
}
async function sendContactMessageReplyAdmin(){
    const submitBtn=document.querySelector('#contactAdminModal .ct-modal-footer .ct-btn.primary[type="submit"]');
    try{
        const id=window.currentContactReplyId;
        const reply=document.getElementById('contactReplyText')?.value.trim()||'';
        const send_sms=!!document.getElementById('contactReplySendSms')?.checked;
        const status=['in_progress','closed','spam'].includes(window.currentContactReplyStatus)?window.currentContactReplyStatus:undefined;
        if(reply.length<3)throw new Error('متن پاسخ را وارد کنید');
        if(submitBtn){submitBtn.disabled=true;submitBtn.classList.add('is-saving');submitBtn.innerHTML='<i class="fas fa-spinner fa-spin"></i> در حال ارسال...';}
        const res=await fetchAPI(`/admin/contact-messages/${id}/reply`,{method:'POST',body:JSON.stringify({reply,send_sms,status})});
        showToast(res.message||'پاسخ ثبت و ارسال شد','success');
        closeContactModal();
        await loadContactMessagesAdmin(contactMessagesState.page||1);
    }catch(error){
        showToast(error.message||'خطا در ثبت پاسخ','error');
        if(submitBtn){submitBtn.disabled=false;submitBtn.classList.remove('is-saving');submitBtn.innerHTML='<i class="fas fa-save"></i> ثبت پاسخ و ارسال';}
    }
}
async function updateContactMessageStatusAdmin(id,status){
    try{
        await fetchAPI(`/admin/contact-messages/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});
        showToast('وضعیت پیام تغییر کرد','success');
        loadContactMessagesAdmin(contactMessagesState.page||1);
    }catch(error){showToast(error.message||'خطا در تغییر وضعیت','error');}
}


function openContactModal(title, fieldsHtml, saveFn, options={}){document.getElementById('contactAdminModal')?.remove();const guide=options.guide||'اطلاعات را ویرایش کنید؛ بعد از ذخیره، تغییرات روی صفحه ارتباط با ما اعمال می‌شود.';const icon=options.icon||'fa-headset';const aiTools=options.aiTools===false?'':`<div class="ct-ai-row"><button class="ct-btn primary" type="button" onclick="contactRewriteTextAI()"><i class="fas fa-wand-magic-sparkles"></i> اصلاح متن</button><button class="ct-btn soft" type="button" onclick="contactFillBlanksAI()"><i class="fas fa-sparkles"></i> پر کردن خالی‌ها</button></div><div id="contactTextStatus" class="ct-status"></div>`;document.body.insertAdjacentHTML('beforeend',`<div class="ct-modal-overlay" id="contactAdminModal" onclick="contactModalBackdrop(event)"><div class="ct-modal ${options.wide?'ct-modal-wide':''}" onclick="event.stopPropagation()" role="dialog" aria-modal="true"><header class="ct-modal-header"><div class="ct-modal-title"><span class="ct-modal-title-icon"><i class="fas ${contactEscape(icon)}"></i></span><div><h3>${contactEscape(title)}</h3><p>${contactEscape(guide)}</p></div></div><button class="ct-close" type="button" onclick="closeContactModal()" aria-label="بستن"><i class="fas fa-times"></i></button></header><form class="ct-modal-form" onsubmit="event.preventDefault();${saveFn}()"><div class="ct-modal-body"><section class="ct-card"><div class="ct-form-grid">${fieldsHtml}</div>${aiTools}</section></div><footer class="ct-modal-footer"><button class="ct-btn primary" type="submit"><i class="fas fa-save"></i> ${contactEscape(options.saveText||'ذخیره و اعمال')}</button><button class="ct-btn soft" type="button" onclick="closeContactModal()"><i class="fas fa-times"></i> ${contactEscape(options.cancelText||'انصراف')}</button></footer></form></div></div>`);document.body.classList.add('modal-open');setTimeout(contactBindModalCounters,0);}
function contactModalBackdrop(e){if(e.target?.id==='contactAdminModal')closeContactModal();}function closeContactModal(){document.getElementById('contactAdminModal')?.remove();document.body.classList.remove('modal-open');}
