function openContactMapModal(){const d=normalizeContactPageAdminContent(contactPageAdminContent);openContactModal('ویرایش موقعیت مدرسه',contactInput('عنوان','contactMapTitle',d.map.title)+contactInput('متن دکمه','contactMapButtonText',d.map.button_text)+contactText('زیرعنوان','contactMapSubtitle',d.map.subtitle,true)+contactText('آدرس','contactMapAddress',d.map.address,true)+contactInput('لینک نقشه نشان','contactMapButtonLink',d.map.button_link,true)+contactInput('Embed URL یا کد iframe نقشه نشان','contactMapEmbed',d.map.embed_url,true)+contactInput('کلید API نشان برای خواندن خودکار آدرس','contactNeshanApiKey',contactPageNeshanApiKey,true)+`<div class="ct-field full"><span>راهنما</span><div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:18px;padding:1rem;color:#1e40af;font-weight:900;line-height:1.9">دکمه «خواندن آدرس از نشان» آدرس دقیق را از لوکیشن پایین می‌خواند. برای دریافت آدرس کامل، کلید API نشان را همین‌جا وارد کنید و ذخیره کنید.</div></div>`,'saveContactMapModal');setTimeout(()=>{const row=document.querySelector('#contactAdminModal .ct-ai-row');if(row&&!document.getElementById('contactResolveAddressBtn'))row.insertAdjacentHTML('afterbegin','<button id="contactResolveAddressBtn" class="ct-btn soft" type="button" onclick="contactResolveNeshanAddress()"><i class="fas fa-location-crosshairs"></i> خواندن آدرس از نشان</button>');},0);}
async function saveContactMapModal(){const d=normalizeContactPageAdminContent(contactPageAdminContent);d.map.title=document.getElementById('contactMapTitle')?.value.trim()||d.map.title;d.map.subtitle=document.getElementById('contactMapSubtitle')?.value.trim()||d.map.subtitle;d.map.address=document.getElementById('contactMapAddress')?.value.trim()||d.map.address;d.map.button_text=document.getElementById('contactMapButtonText')?.value.trim()||d.map.button_text;const rawLink=document.getElementById('contactMapButtonLink')?.value.trim()||d.map.button_link;const rawEmbed=String(document.getElementById('contactMapEmbed')?.value||'').trim();d.map.button_link=contactShortNeshanLinkAdmin2(rawLink)||rawLink;d.map.embed_url=contactExtractIframeSrcAdmin(rawEmbed)||contactNeshanIframeUrlAdmin(rawLink)||d.map.embed_url;contactPageNeshanApiKey=document.getElementById('contactNeshanApiKey')?.value.trim()||contactPageNeshanApiKey;try{if(contactPageNeshanApiKey&&(contactLooksLikePlaceholderAddressAdmin(d.map.address)||!d.map.address)){const resolved=await contactResolveNeshanAddress(true);if(resolved?.address)d.map.address=resolved.address;}}catch(e){}if(d.map.address){d.methods=(d.methods||[]).map(method=>contactIsAddressMethodAdmin2(method)?{...method,value:d.map.address,link:d.map.button_link||d.map.embed_url||method.link}:method);}persistContactPageAdminContent(contactSyncManualAddressAdmin(d),'نقشه ذخیره شد');}
function contactSocialIdFromTitleAdmin(title='',index=0){const text=String(title||'').toLowerCase();if(/شاد|shad/.test(text))return'shad';if(/بله|bale/.test(text))return'bale';if(/ایتا|eitaa|ita/.test(text))return'eitaa';return `social-${index+1}`;}
function contactSocialRowHtmlAdmin(item={},index=0){return `<div class="ct-social-row" data-social-row><label class="ct-field"><span>نام برنامه</span><input data-social-title value="${contactEscape(item.title||'')}" maxlength="80" placeholder="مثلاً شاد، بله یا ایتا" autocomplete="off"></label><label class="ct-field"><span>لینک یا آدرس دکمه</span><input data-social-link value="${contactEscape(item.link||'')}" maxlength="500" placeholder="https://..." autocomplete="off"></label><button class="ct-btn danger ct-social-remove" type="button" onclick="contactRemoveSocialRow(this)"><i class="fas fa-trash"></i> حذف</button></div>`;}
function contactAddSocialRow(item={}){const box=document.getElementById('contactSocialRows');if(!box)return;box.insertAdjacentHTML('beforeend',contactSocialRowHtmlAdmin(item,box.querySelectorAll('[data-social-row]').length));}
function contactRemoveSocialRow(btn){btn.closest('[data-social-row]')?.remove();}
function openContactSocialsModal(){const d=normalizeContactPageAdminContent(contactPageAdminContent);const rows=(d.socials.length?d.socials:[{title:'شاد',link:'#'},{title:'بله',link:'#'},{title:'ایتا',link:'#'}]).map(contactSocialRowHtmlAdmin).join('');openContactModal('ویرایش شبکه‌های اجتماعی',`<div class="ct-field full"><span>شبکه‌های قابل نمایش</span><div id="contactSocialRows" class="ct-social-rows">${rows}</div><button class="ct-btn soft ct-add-row" type="button" onclick="contactAddSocialRow()"><i class="fas fa-plus"></i> افزودن شبکه</button><small class="ct-field-help">برای هر شبکه فقط نام برنامه و لینک دکمه را وارد کنید؛ آیکن به‌صورت خودکار تشخیص داده می‌شود.</small></div>`,'saveContactSocialsModal',{icon:'fa-share-nodes',aiTools:false,wide:true});}
function saveContactSocialsModal(){try{const d=normalizeContactPageAdminContent(contactPageAdminContent);const rows=[...document.querySelectorAll('#contactSocialRows [data-social-row]')];d.socials=rows.map((row,i)=>{const title=String(row.querySelector('[data-social-title]')?.value||'').trim();const link=String(row.querySelector('[data-social-link]')?.value||'').trim();if(!title&&!link)return null;if(!title)throw new Error('نام برنامه در یکی از شبکه‌ها خالی است');if(!link)throw new Error(`لینک ${title} خالی است`);const item={id:contactSocialIdFromTitleAdmin(title,i),title,link};return{...item,icon:contactAutoSocialIconAdmin(item)};}).filter(Boolean);if(!d.socials.length)throw new Error('حداقل یک شبکه اجتماعی ثبت کنید');persistContactPageAdminContent(d,'شبکه‌های اجتماعی ذخیره شد');}catch(error){showToast(error.message||'شبکه‌ها ذخیره نشد','error');}}
function openContactCtaModal(){const d=normalizeContactPageAdminContent(contactPageAdminContent);openContactModal('ویرایش بخش پایانی',contactInput('عنوان','contactCtaTitle',d.cta.title,true)+contactText('توضیح','contactCtaSubtitle',d.cta.subtitle,true)+contactInput('متن دکمه','contactCtaButtonText',d.cta.button_text)+contactInput('لینک دکمه','contactCtaButtonLink',d.cta.button_link),'saveContactCtaModal');}
function saveContactCtaModal(){const d=normalizeContactPageAdminContent(contactPageAdminContent);d.cta.title=document.getElementById('contactCtaTitle')?.value.trim()||d.cta.title;d.cta.subtitle=document.getElementById('contactCtaSubtitle')?.value.trim()||d.cta.subtitle;d.cta.button_text=document.getElementById('contactCtaButtonText')?.value.trim()||d.cta.button_text;d.cta.button_link=document.getElementById('contactCtaButtonLink')?.value.trim()||d.cta.button_link;persistContactPageAdminContent(d,'بخش پایانی ذخیره شد');}


function contactKnownNeshanAddressAdmin(map={}){return '';}
function contactIsUsefulTextAddressAdmin(value=''){const text=String(value||'').trim();const hasStreet=/استان|شهر|تهران|اندیشه|شهریار|خیابان|بلوار|میدان|کوچه|بزرگراه|چهارراه|محله|ناحیه|منطقه/.test(text);const onlyPlace=/^مدرسه\s+/.test(text)&&!/[،,]/.test(text)&&!/خیابان|بلوار|کوچه|شهر|استان/.test(text);return !!text&&hasStreet&&!onlyPlace;}

function contactLooksLikePlaceholderAddressAdmin(address=''){const text=String(address||'').trim();return !text||/تهران،\s*خیابان اصلی|مدیریت هوشمند|نشانی مدرسه|آدرس مدرسه/i.test(text);}
async function contactResolveNeshanAddress(silent=false){
    const st=document.getElementById('contactTextStatus');
    try{
        const apiKey=document.getElementById('contactNeshanApiKey')?.value.trim()||contactPageNeshanApiKey||'';
        const map={
            title:document.getElementById('contactMapTitle')?.value.trim()||'موقعیت مدرسه',
            subtitle:document.getElementById('contactMapSubtitle')?.value.trim()||'',
            address:document.getElementById('contactMapAddress')?.value.trim()||'',
            button_text:document.getElementById('contactMapButtonText')?.value.trim()||'مشاهده مسیر',
            button_link:document.getElementById('contactMapButtonLink')?.value.trim()||'',
            embed_url:document.getElementById('contactMapEmbed')?.value.trim()||''
        };
        if(!apiKey) throw new Error('کلید API نشان را وارد کنید تا آدرس خودکار خوانده شود.');
        if(!map.embed_url&&!map.button_link) throw new Error('کد iframe یا لینک نشان را وارد کنید.');
        if(st&&!silent) st.textContent='در حال دریافت آدرس واقعی از نشان...';
        const res=await fetchAPI('/admin/contact-page/resolve-address',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({map,neshan_api_key:apiKey})});
        if(res.address){
            contactPageNeshanApiKey=apiKey;
            const addressEl=document.getElementById('contactMapAddress');
            if(addressEl) addressEl.value=res.address;
            if(res.map?.embed_url&&document.getElementById('contactMapEmbed')) document.getElementById('contactMapEmbed').value=res.map.embed_url;
            if(res.map?.button_link&&document.getElementById('contactMapButtonLink')) document.getElementById('contactMapButtonLink').value=res.map.button_link;
            if(st&&!silent) st.textContent='آدرس واقعی از نشان خوانده شد.';
            if(!silent) showToast('آدرس از نشان دریافت شد','success');
            return res;
        }
        throw new Error('آدرسی از نشان دریافت نشد.');
    }catch(error){
        if(st&&!silent) st.textContent=error.message||'دریافت آدرس انجام نشد';
        if(!silent) showToast(error.message||'دریافت آدرس انجام نشد','error');
        throw error;
    }
}

function contactCollectModalFields(){const fields={};document.querySelectorAll('#contactAdminModal input[id],#contactAdminModal textarea[id]').forEach(el=>{if(/Link|Url|Icon|Phone|Mobile|Email/i.test(el.id))return;if(el.type==='checkbox')return;fields[el.id]=String(el.value||'').trim();});return fields;}
function contactApplyFields(fields={}){Object.entries(fields||{}).forEach(([id,value])=>{const el=document.getElementById(id);if(el&&value!=null)el.value=String(value);});}
function contactContextTitle(){return document.getElementById('contactMethodTitle')?.value.trim()||document.getElementById('contactHeroTitle')?.value.trim()||document.getElementById('contactCtaTitle')?.value.trim()||'ارتباط با مدرسه';}
async function contactRewriteTextAI(){const st=document.getElementById('contactTextStatus');try{const fields=contactCollectModalFields();if(!Object.values(fields).some(Boolean))throw new Error('متنی برای بازنویسی وجود ندارد');if(st)st.textContent='در حال بازنویسی حرفه‌ای متن‌ها...';const res=await fetchAPI('/admin/contact-page/ai-rewrite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:contactContextTitle(),fields})});contactApplyFields(res.fields||{});if(st)st.textContent='متن‌ها با توجه به محتوای همین مودال بازنویسی شدند.';}catch(error){if(st)st.textContent=error.message||'بازنویسی انجام نشد';showToast(error.message||'بازنویسی انجام نشد','error');}}
async function contactFillBlanksAI(){const st=document.getElementById('contactTextStatus');try{const fields=contactCollectModalFields();const empty_ids=Object.entries(fields).filter(([id,value])=>!String(value||'').trim()).map(([id])=>id);if(!empty_ids.length){if(st)st.textContent='فیلد خالی برای تکمیل وجود ندارد.';return;}if(st)st.textContent='در حال تکمیل فیلدهای خالی...';const res=await fetchAPI('/admin/contact-page/ai-complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:contactContextTitle(),fields,empty_ids})});contactApplyFields(res.fields||{});if(st)st.textContent='فیلدهای خالی با توجه به محتوای همین مودال تکمیل شدند.';}catch(error){if(st)st.textContent=error.message||'تکمیل انجام نشد';showToast(error.message||'تکمیل انجام نشد','error');}}
async function loadContactPageAdmin(){const contentArea=document.getElementById('contentArea');try{showLoading(true);const res=await fetchAPI('/admin/contact-page?_='+Date.now(),{cache:'no-store'});contactPageNeshanApiKey=String(res.neshan_api_key||'');contactPageAdminContent=contactApplyFinalAddressAdmin(res.content||{});renderContactPageAdmin(contactPageAdminContent,res.stats||{});}catch(error){if(contentArea)contentArea.innerHTML=`<div class="empty-state"><i class="fas fa-triangle-exclamation"></i><h3>خطا در بارگذاری ارتباط با ما</h3><p>${contactEscape(error.message||'ارتباط با سرور برقرار نشد')}</p><button class="btn btn-primary" onclick="loadContactPageAdmin()">تلاش مجدد</button></div>`;}finally{showLoading(false);const lo=document.getElementById('loadingOverlay');if(lo)lo.style.display='none';}}
async function persistContactPageAdminContent(content,message='صفحه ارتباط با ما ذخیره شد'){try{showLoading(true);const payload=contactApplyFinalAddressAdmin(content);const res=await fetchAPI('/admin/contact-page',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:payload,neshan_api_key:contactPageNeshanApiKey})});contactPageAdminContent=normalizeContactPageAdminContent(res.content||payload);closeContactModal();renderContactPageAdmin(contactPageAdminContent,res.stats||{});showToast(message,'success');}catch(error){showToast(error.message||'ذخیره انجام نشد','error');}finally{showLoading(false);}}
