document.addEventListener('DOMContentLoaded', function() {
    initPersianNumberObserver();
    const fullscreenBtn = document.getElementById('fullscreenBtn');
    if (fullscreenBtn) {
        fullscreenBtn.addEventListener('click', function() {
            if (!document.fullscreenElement) {
                document.documentElement.requestFullscreen();
                this.innerHTML = '<i class="fas fa-compress"></i>';
            } else {
                document.exitFullscreen();
                this.innerHTML = '<i class="fas fa-expand"></i>';
            }
        });
    }
});


function renderAdminSidebarIdentity(user = {}, settings = {}) {
    const adminNameSpan = document.getElementById('adminName');
    const adminRoleSpan = document.getElementById('adminRole');
    const adminAvatar = document.getElementById('adminAvatar');
    const configuredFirstName = String(settings.manager_first_name || settings.admin_first_name || '').trim();
    const configuredLastName = String(settings.manager_last_name || settings.admin_last_name || '').trim();
    const configuredFullName = String(settings.manager_full_name || settings.admin_full_name || '').trim();
    const settingsDisplayName = configuredFullName || `${configuredFirstName} ${configuredLastName}`.trim();
    const displayName = String(settingsDisplayName || user.name || user.full_name || 'مدیر مدرسه').trim() || 'مدیر مدرسه';
    const roleLabel = getRoleName(user.role || 'admin') || 'مدیر مدرسه';
    const avatarUrl = String(settings.admin_profile_avatar_url || settings.manager_avatar_url || user.avatar_url || user.avatar || user.profile_photo || user.profile_photo_url || user.photo_url || '').trim();

    if (adminNameSpan) adminNameSpan.textContent = displayName;
    if (adminRoleSpan) adminRoleSpan.textContent = roleLabel === 'مدیر سیستم' ? 'مدیر مدرسه' : roleLabel;

    if (!adminAvatar) return;

    if (avatarUrl) {
        adminAvatar.innerHTML = `<img src="${escapeHtml(avatarUrl)}" alt="عکس پروفایل ${escapeHtml(displayName)}">`;
        const img = adminAvatar.querySelector('img');
        if (img) {
            img.addEventListener('error', () => {
                adminAvatar.innerHTML = '<i class="fas fa-user-shield"></i>';
            }, { once: true });
        }
    } else {
        adminAvatar.innerHTML = '<i class="fas fa-user-shield"></i>';
    }
}

function renderAdminSidebarBrand(settings = {}) {
    const schoolName = String(settings.school_name || settings.name || 'مدیریت هوشمند').trim() || 'مدیریت هوشمند';
    const schoolSlogan = String(settings.school_slogan || settings.slogan || 'پنل مدیریت مدرسه').trim() || 'پنل مدیریت مدرسه';
    const logoUrl = String(settings.logo_url || settings.school_logo || settings.logo || '').trim();
    const nameEl = document.getElementById('adminSchoolName');
    const subtitleEl = document.getElementById('adminSchoolSubtitle');
    const logoEl = document.getElementById('adminSchoolLogo');

    if (nameEl) nameEl.textContent = schoolName;
    if (subtitleEl) subtitleEl.textContent = schoolSlogan;

    if (!logoEl) return;
    if (logoUrl) {
        logoEl.innerHTML = `<img src="${escapeHtml(logoUrl)}" alt="لوگوی ${escapeHtml(schoolName)}">`;
        const img = logoEl.querySelector('img');
        if (img) {
            img.addEventListener('error', () => {
                logoEl.innerHTML = '<i class="fas fa-graduation-cap"></i>';
            }, { once: true });
        }
    } else {
        logoEl.innerHTML = '<i class="fas fa-graduation-cap"></i>';
    }
}

async function loadAdminSidebarBrand() {
    renderAdminSidebarBrand();
    try {
        const payload = await fetchAPI('/settings');
        const settings = payload?.settings || payload || {};
        settingsData = { ...(settingsData || {}), ...settings };
        renderAdminSidebarBrand(settings);
        renderAdminSidebarIdentity(currentUser || {}, settings);
        return settings;
    } catch (error) {
        console.warn('Admin sidebar school settings could not be loaded:', error);
        return {};
    }
}

function getInitialPanelPage() {
    const page = document.body && document.body.dataset ? document.body.dataset.page : null;
    return page || 'dashboard';
}

async function init() {
    const token = getToken();
    if (!token) {
        redirectToLogin();
        return;
    }
    
    showLoading(true);
    try {
        let user;
        try {
            user = await fetchAPI('/auth/me');
        } catch (authLoadError) {
            if (authLoadError?.status === 429) {
                try { user = JSON.parse(localStorage.getItem('user') || 'null'); } catch (_) { user = null; }
            } else {
                throw authLoadError;
            }
        }

        // جلوگیری از ورود نقش‌های دیگر به پنل مدیریت
        if (!user || user.role !== 'admin') {
            clearAuthSession();
            redirectToLogin();
            return;
        }

        currentUser = user;
        try { localStorage.setItem('user', JSON.stringify(user)); } catch (_) {}
        ensureAdminScheduleNav();
        ensureAdminHomepageNav();
        renderAdminSidebarIdentity(user);
        await loadAdminSidebarBrand();
        showTab(getInitialPanelPage());
    } catch (error) {
        if (error.name !== 'AuthenticationError') {
            console.error('Admin initialization error:', error);
            const contentArea = document.getElementById('contentArea');
            if (contentArea) {
                contentArea.innerHTML = `
                    <div class="empty-state">
                        <i class="fas fa-exclamation-triangle fa-3x" style="color:#f59e0b;margin-bottom:15px;"></i>
                        <h4>خطا در بارگذاری پنل مدیریت</h4>
                        <p>${error.message || 'ارتباط با سرور برقرار نشد'}</p>
                        <button class="btn btn-primary mt-3" onclick="window.location.reload()">
                            <i class="fas fa-redo"></i> تلاش مجدد
                        </button>
                    </div>
                `;
            }
            showToast('خطا در بارگذاری اطلاعات', 'error');
        }
    } finally {
        if (!authRedirectInProgress) showLoading(false);
    }
}


