function adminOpenReportGradeModal(trigger){
    const raw = trigger?.getAttribute?.('data-payload') || '{}';
    let ctx = {};
    try{ ctx = JSON.parse(raw); }catch(e){ ctx = {}; }
    if(!ctx.student_id || !ctx.course_id){ showToast('ابتدا پایه، کلاس و دانش‌آموز را انتخاب کنید','warning'); return; }
    const mode = ctx.grade_mode === 'descriptive' ? 'descriptive' : 'numeric';
    const title = `${ctx.id ? 'ویرایش نمره' : 'ثبت نمره'} - ${ctx.course_name || ''}`;
    const descLevels = ADMIN_GRADE_MODULE_CACHE.options?.descriptiveLevels || [];
    const field = mode === 'descriptive'
        ? adminRenderSmartDropdown('grade_text', descLevels, ctx.grade_text || 'good', 'انتخاب سطح توصیفی', 'جستجو در سطح‌ها...')
        : `<input class="amp-input" name="grade_value" type="number" min="0" max="20" step="0.25" value="${adminModuleEscape(ctx.grade_value ?? '')}" placeholder="مثلاً ۱۸.۵" required>`;
    adminOpenModuleUtilityModal(title, `<div class="arc-mini-modal-note"><i class="fas fa-circle-info"></i> ${adminModuleEscape(ctx.column_label || '')}</div><form class="arc-single-grade-form" id="adminReportGradeCellForm" data-context="${adminReportPayloadAttr(ctx)}" onsubmit="adminSubmitReportGrade(event)"><div class="amp-field"><label>نمره <span>*</span></label>${field}</div><div class="amp-modal-actions"><button class="amp-btn primary" type="submit"><i class="fas fa-save"></i> ثبت نمره</button><button class="amp-btn white" type="button" onclick="adminCloseModuleUtilityModal()">انصراف</button></div></form>`, '430px');
    setTimeout(() => {
        const form = document.getElementById('adminReportGradeCellForm');
        const input = mode === 'descriptive' ? form?.querySelector('.amp-smart-trigger') : form?.querySelector('input,select');
        input?.focus?.();
    }, 40);
}
async function adminSubmitReportGrade(event){
    event?.preventDefault?.();
    const form = event?.target?.tagName === 'FORM' ? event.target : event?.target?.closest?.('form');
    if(!form || form.dataset.saving === '1') return;
    let ctx = {};
    try{ ctx = JSON.parse(form.dataset.context || '{}'); }catch(e){ ctx = {}; }
    const mode = ctx.grade_mode === 'descriptive' ? 'descriptive' : 'numeric';
    const payload = {
        student_id: ctx.student_id,
        course_id: ctx.course_id,
        class_id: ctx.class_id || null,
        grade_type: ctx.grade_type,
        term: ctx.term,
        academic_year: 'سال تحصیلی جاری',
        grade_mode: mode,
        notes: '',
        change_reason: 'ثبت کارنامه از جدول مدیریتی'
    };
    if(mode === 'descriptive'){
        payload.grade_text = form.querySelector('[name="grade_text"]')?.value || 'good';
    }else{
        const value = Number(form.querySelector('[name="grade_value"]')?.value);
        if(!Number.isFinite(value) || value < 0 || value > 20){ showToast('نمره باید بین ۰ تا ۲۰ باشد','warning'); return; }
        payload.grade_value = value;
    }
    form.dataset.saving = '1';
    form.querySelectorAll('button,input,select').forEach(el => el.disabled = true);
    try{
        const endpoint = ctx.id ? `/admin/modules/grades/${ctx.id}` : '/admin/modules/grades';
        const saved = await fetchAPI(endpoint, { method: ctx.id ? 'PUT' : 'POST', body: JSON.stringify(payload) });
        if (saved && saved.success === false) throw new Error(saved.error || saved.message || 'ثبت نمره انجام نشد');
        adminInvalidateReadCaches(['/admin/modules/grades', '/admin/modules/grades/options']);
        showToast(ctx.id ? 'نمره ویرایش شد' : 'نمره ثبت شد', 'success');
        adminCloseModuleUtilityModal?.();
        await adminApplyGradeFilters();
    }catch(error){
        showToast(error.message || 'خطا در ثبت نمره', 'error');
        form.dataset.saving = '0';
        form.querySelectorAll('button,input,select').forEach(el => el.disabled = false);
    }
}
async function adminDeleteReportGrade(id){
    if(!id || !confirm('این نمره حذف شود؟')) return;
    try{
        await fetchAPI(`/admin/modules/grades/${id}`, { method:'DELETE' });
        adminInvalidateReadCaches(['/admin/modules/grades', '/admin/modules/grades/options']);
        showToast('نمره حذف شد', 'success');
        await adminApplyGradeFilters();
    }catch(error){ showToast(error.message || 'خطا در حذف نمره', 'error'); }
}

function adminRenderGenericModuleFallback(pageConfig = {}, rows = []){
    const title = adminModuleEscape?.(pageConfig.title || 'ماژول') || 'ماژول';
    const desc = adminModuleEscape?.(pageConfig.description || 'داده‌ای برای نمایش وجود ندارد.') || '';
    return `<div class="admin-module-pro">${typeof adminModuleScopedStyles === 'function' ? adminModuleScopedStyles() : ''}<section class="amp-panel"><div class="amp-panel-head"><div class="amp-title"><i class="fas ${pageConfig.icon||'fa-table'}"></i><div><h3>${title}</h3><p>${desc}</p></div></div></div><div class="amp-panel-body">${typeof adminModuleTable === 'function' ? adminModuleTable(rows || [], []) : '<div class="amp-empty">داده‌ای برای نمایش وجود ندارد.</div>'}</div></section></div>`;
}

function adminRenderConsolidatedModulePage(pageKey, page = {}, data = {}, rows = [], summary = {}){
    if(pageKey === 'grades'){
        ADMIN_GRADE_MODULE_CACHE.options = data.options || ADMIN_GRADE_MODULE_CACHE.options || {};
        ADMIN_GRADE_MODULE_CACHE.rows = rows || [];
        const filters = adminReportCleanFilters(ADMIN_GRADE_MODULE_CACHE.filters || {});
        const ready = adminReportRequiredReady(filters);
        return `<div class="admin-module-pro amp-page-gradeatt amp-page-report-card-grid">${adminModuleScopedStyles()}${adminReportCardGridStyles()}
            <section class="amp-control-panel arc-grade-hero">
                <div class="amp-control-copy">
                    <span class="amp-control-badge"><i class="fas fa-award"></i> ثبت کارنامه</span>
                    <h3>مدیریت نمرات به‌صورت جدولی</h3>
                    <p>ابتدا پایه، کلاس و دانش‌آموز را انتخاب کنید؛ سپس نمره‌های مستمر و پایانی هر نوبت را مستقیم داخل خانه‌های جدول ثبت، ویرایش یا حذف کنید.</p>
                    <div class="amp-control-meta">
                        <span><i class="fas fa-layer-group"></i> فیلتر اجباری پایه، کلاس و دانش‌آموز</span>
                        <span><i class="fas fa-table-cells-large"></i> ساختار جدولی مشابه برنامه هفتگی</span>
                        <span><i class="fas fa-pen-to-square"></i> ثبت، ویرایش و حذف داخل خانه‌ها</span>
                    </div>
                </div>
                <div class="arc-grade-status ${ready ? 'ready' : ''}">
                    <i class="fas ${ready ? 'fa-check-circle' : 'fa-circle-info'}"></i>
                    <strong>${ready ? 'آماده ثبت نمره' : 'در انتظار تکمیل فیلترها'}</strong>
                    <span>${ready ? 'جدول درس‌ها فعال است و می‌توانید ثبت نمره را آغاز کنید.' : 'برای فعال شدن جدول، پایه، کلاس و دانش‌آموز را انتخاب کنید.'}</span>
                </div>
            </section>
            ${adminRenderReportCardFilterBar(data)}
            ${adminRenderReportCardGrid(data, rows)}
        </div>`;
    }
    if(typeof adminRenderAttendanceProfessionalPage === 'function' && pageKey === 'attendance'){
        return adminRenderAttendanceProfessionalPage(data, rows, summary);
    }
    return adminRenderGenericModuleFallback(page || pageKey || {}, rows || []);
}

/* Grades table-page loader fix - restores the real report-card matrix UI without changing other modules */
(function(){
    if (window.__gradesReportCardMatrixLoaderFixV4) return;
    window.__gradesReportCardMatrixLoaderFixV4 = true;
    const previousGradeModuleLoader = window.loadAdminNewModulePage;

    function cleanGradeFilters(raw = {}){
        const result = {};
        ['grade','class_id','student_id'].forEach(key => {
            const value = String(raw?.[key] ?? '').trim();
            if(value && value !== 'all') result[key] = value;
        });
        return result;
    }

    async function loadGradesReportCardMatrix(filters = {}){
        const contentArea = document.getElementById('contentArea');
        const cleaned = cleanGradeFilters(filters && Object.keys(filters).length ? filters : (ADMIN_GRADE_MODULE_CACHE?.filters || {}));
        if(contentArea && !contentArea.innerHTML.trim()){
            contentArea.innerHTML = '<div class="empty-state"><i class="fas fa-spinner fa-spin"></i><p>در حال بارگذاری مدیریت نمرات...</p></div>';
        }
        try { showLoading?.(true); } catch(e) {}
        try{
            let data;
            const params = new URLSearchParams();
            Object.entries(cleaned).forEach(([key,value]) => params.set(key, value));
            const hasRequired = Boolean(cleaned.grade && cleaned.class_id && cleaned.student_id);
            if(hasRequired){
                params.set('_fresh', String(Date.now()));
                data = await fetchAPI('/admin/modules/grades' + (params.toString() ? '?' + params.toString() : ''));
            }else{
                const optParams = new URLSearchParams();
                ['grade','class_id','student_id'].forEach(key => { if(cleaned[key]) optParams.set(key, cleaned[key]); });
                optParams.set('_fresh', String(Date.now()));
                const opt = await fetchAPI('/admin/modules/grades/options' + (optParams.toString() ? '?' + optParams.toString() : ''));
                data = { success:true, options: opt.options || ADMIN_GRADE_MODULE_CACHE?.options || {}, items: [], grades: [], summary: {} };
            }
            ADMIN_GRADE_MODULE_CACHE = { options: data.options || ADMIN_GRADE_MODULE_CACHE?.options || {}, rows: data.items || data.grades || [], filters: cleaned };
            if(contentArea){
                contentArea.innerHTML = adminRenderConsolidatedModulePage('grades', ADMIN_NEW_MODULE_PAGES.grades, data, data.items || data.grades || [], data.summary || {});
                try { bindAdminModuleForms?.('grades'); } catch(e) {}
                try { upgradeUsersSelects?.(contentArea); } catch(e) {}
                try { adminInitSmartDropdowns?.(contentArea); } catch(e) {}
            }
        }catch(error){
            console.error('Grades matrix loader failed:', error);
            if(contentArea){
                const msg = adminModuleEscape?.(error.message || 'ارتباط با سرور برقرار نشد') || '';
                contentArea.innerHTML = `<div class="empty-state"><i class="fas fa-triangle-exclamation"></i><h3>خطا در بارگذاری مدیریت نمرات</h3><p>${msg}</p><button class="btn btn-primary" onclick="loadAdminNewModulePage('grades')">تلاش مجدد</button></div>`;
            }
            try { showToast?.(error.message || 'خطا در بارگذاری مدیریت نمرات','error'); } catch(e) {}
        }finally{
            try { showLoading?.(false); const lo=document.getElementById('loadingOverlay'); if(lo) lo.style.display='none'; } catch(e) {}
        }
    }

    window.loadGrades = loadGradesReportCardMatrix;
    window.loadAdminGradesPage = loadGradesReportCardMatrix;
    window.loadAdminNewModulePage = function(pageKey){
        if(['grades','grades-view','grades-create','grades-edit','grade-reports'].includes(pageKey)) return loadGradesReportCardMatrix(ADMIN_GRADE_MODULE_CACHE?.filters || {});
        return typeof previousGradeModuleLoader === 'function' ? previousGradeModuleLoader.apply(this, arguments) : undefined;
    };
    try { loadAdminNewModulePage = window.loadAdminNewModulePage; } catch(e) {}
})();
